const readSetupBoolean = (
  value,
  fallback = false
) => {
  if (typeof value === "boolean") {
    return value;
  }

  if (typeof value === "number") {
    return value === 1;
  }

  const normalizedValue = String(
    value ?? ""
  )
    .trim()
    .toUpperCase();

  if (
    ["TRUE", "1", "Y", "YES", "ON"].includes(
      normalizedValue
    )
  ) {
    return true;
  }

  if (
    ["FALSE", "0", "N", "NO", "OFF"].includes(
      normalizedValue
    )
  ) {
    return false;
  }

  return fallback;
};

const loadLatestSalesPrintSetup =
  async () => {
    const distributorId = String(
      localStorage.getItem("distributorId") ||
      ""
    ).trim();

    const firmId = String(
      localStorage.getItem("firmId") ||
      ""
    ).trim();

    if (!distributorId || !firmId) {
      return {
        ...runtimeGeneralSetup,
      };
    }

    try {
      const query = new URLSearchParams({
        distributorId,
        firmId,
        _time: String(Date.now()),
      });

      const response = await fetch(
        `${API_URL}/general-setup?${query.toString()}`,
        {
          method: "GET",
          cache: "no-store",
          headers: {
            Accept: "application/json",
          },
        }
      );

      const contentType =
        response.headers.get(
          "content-type"
        ) || "";

      const result =
        contentType.includes(
          "application/json"
        )
          ? await response.json()
          : null;

      if (
        !response.ok ||
        result?.success === false
      ) {
        throw new Error(
          result?.message ||
          "Unable to load print settings."
        );
      }

      const setup =
        result?.setup ||
        result?.generalSetup ||
        result?.data ||
        result ||
        {};

      const latestSetup = {
        ...runtimeGeneralSetup,

        goodsReturn:
          readSetupBoolean(
            setup.goodsReturn,
            true
          ),

        damageReturn:
          readSetupBoolean(
            setup.damageReturn,
            true
          ),

        schemeSummary:
          readSetupBoolean(
            setup.schemeSummary,
            true
          ),

        vatSummary:
          readSetupBoolean(
            setup.vatSummary,
            true
          ),

        serialNo:
          readSetupBoolean(
            setup.serialNo,
            false
          ),
      };

      setRuntimeGeneralSetup(
        latestSetup
      );

      console.log(
        "Latest bill print setup:",
        latestSetup
      );

      return latestSetup;
    } catch (error) {
      console.error(
        "Latest print setup load error:",
        error
      );

      return {
        ...runtimeGeneralSetup,
      };
    }
  };
