    window.requestAnimationFrame(() => {
      window.setTimeout(() => {
        const productInput = document.querySelector(
          `[data-product-index="${rowIndex}"]`
        );

        if (productInput) {
          productInput.focus();
          productInput.scrollIntoView({
            behavior: "smooth",
            block: "nearest",
            inline: "nearest",
          });
        }
      }, 50);
    });
