  /* =========================================================
    INDIAN CURRENCY AMOUNT IN WORDS
    Add inside Dashboard component before return()
    ========================================================= */

  const numberToIndianWords = (inputValue) => {
    const number = Math.floor(
      Math.abs(Number(inputValue) || 0)
    );

    if (number === 0) {
      return "Zero";
    }

    const ones = [
      "",
      "One",
      "Two",
      "Three",
      "Four",
      "Five",
      "Six",
      "Seven",
      "Eight",
      "Nine",
      "Ten",
      "Eleven",
      "Twelve",
      "Thirteen",
      "Fourteen",
      "Fifteen",
      "Sixteen",
      "Seventeen",
      "Eighteen",
      "Nineteen",
    ];

    const tens = [
      "",
      "",
      "Twenty",
      "Thirty",
      "Forty",
      "Fifty",
      "Sixty",
      "Seventy",
      "Eighty",
      "Ninety",
    ];

    const convertBelowHundred = (value) => {
      if (value < 20) {
        return ones[value];
      }

      const tenPart = tens[Math.floor(value / 10)];
      const onePart = ones[value % 10];

      return `${tenPart}${onePart ? ` ${onePart}` : ""}`;
    };

    const convertBelowThousand = (value) => {
      const hundredPart = Math.floor(value / 100);
      const remainingPart = value % 100;

      const result = [];

      if (hundredPart > 0) {
        result.push(`${ones[hundredPart]} Hundred`);
      }

      if (remainingPart > 0) {
        result.push(convertBelowHundred(remainingPart));
      }

      return result.join(" ");
    };

    let remaining = number;
    const result = [];

    const crore = Math.floor(remaining / 10000000);

    if (crore > 0) {
      result.push(
        `${numberToIndianWords(crore)} Crore`
      );

      remaining %= 10000000;
    }

    const lakh = Math.floor(remaining / 100000);

    if (lakh > 0) {
      result.push(
        `${convertBelowThousand(lakh)} Lakh`
      );

      remaining %= 100000;
    }

    const thousand = Math.floor(remaining / 1000);

    if (thousand > 0) {
      result.push(
        `${convertBelowThousand(thousand)} Thousand`
      );

      remaining %= 1000;
    }

    if (remaining > 0) {
      result.push(convertBelowThousand(remaining));
    }

    return result.join(" ").trim();
  };

  const convertAmountToWords = (inputValue) => {
    const numericValue = Number(inputValue) || 0;
    const absoluteValue = Math.abs(numericValue);

    const rupees = Math.floor(absoluteValue);

    const paise = Math.round(
      (absoluteValue - rupees) * 100
    );

    let words = `${numberToIndianWords(rupees)} Rupees`;

    if (paise > 0) {
      words += ` and ${numberToIndianWords(
        paise
      )} Paise`;
    }

    return `${words} Only`;
  };


