  const buildFilteredProductList = (
    searchTerm,
    editingIndex = -1
  ) => {
    const search = norm(searchTerm);

    const selectionMode =
      getRuntimeProductSelectionMode();

    const usedKeys = new Set(
      invoiceItems
        .filter(
          (_, itemIndex) =>
            itemIndex !== editingIndex
        )
        .filter(
          (item) =>
            item?.productCode ||
            item?.productId
        )
        .map(getInvoiceItemKey)
    );

    const getSelectedSearchValue = (
      product
    ) => {
      switch (selectionMode) {
        case "COMPANY_PRODUCT_CODE":
          return getProductCompanyCode(
            product
          );

        case "SHORT_CODE":
          return getProductShortCode(
            product
          );

        case "LOCAL_PRODUCT_NAME":
          return getProductLocalName(
            product
          );

        case "EAN_NO":
          return getProductEanNo(
            product
          );

        case "PRODUCT_NAME":
          return getProductName(
            product
          );

        case "PRODUCT_CODE":
        default:
          return getProductCode(
            product
          );
      }
    };

    const entries =
      getFilteredSalesProducts()
        .filter((product) => {
          if (!search) {
            return true;
          }

          const selectedValue =
            getSelectedSearchValue(
              product
            );

          return norm(
            selectedValue
          ).includes(search);
        })
        .sort(
          (
            firstProduct,
            secondProduct
          ) => {
            const firstValue =
              getSelectedSearchValue(
                firstProduct
              );

            const secondValue =
              getSelectedSearchValue(
                secondProduct
              );

            return String(
              firstValue || ""
            ).localeCompare(
              String(
                secondValue || ""
              ),
              undefined,
              {
                numeric: true,
                sensitivity: "base",
              }
            );
          }
        )
        .flatMap((product) => {
          const productBatches =
            getCachedSalesBatches(
              product
            );

          if (
            productBatches.length > 0
          ) {
            return productBatches.map(
              (batch) => ({
                product,
                batch,

                searchValue:
                  getSelectedSearchValue(
                    product
                  ),

                selectionMode,

                isAlreadySelected:
                  usedKeys.has(
                    getSalesProductKey(
                      product,
                      batch
                    )
                  ),
              })
            );
          }

          return [
            {
              product,
              batch: null,

              searchValue:
                getSelectedSearchValue(
                  product
                ),

              selectionMode,

              isAlreadySelected:
                usedKeys.has(
                  getSalesProductKey(
                    product,
                    null
                  )
                ),
            },
          ];
        });

    setFilteredProductList(
      entries
    );

    setProductDropdownIndex(
      entries.length > 0
        ? 0
        : -1
    );
  };
