  const loadAreasForAccount = async () => {
    try {
      const distributorId = localStorage.getItem("distributorId");
      const firmId = localStorage.getItem("firmId");

      console.log("🔍 loadAreasForAccount called with:", { distributorId, firmId });

      if (!distributorId || !firmId) {
        console.warn("⚠️ No distributorId or firmId found in localStorage");
        setAreaOptions([]);
        return;
      }

      const url = `${API_URL}/areas-for-account?distributorId=${encodeURIComponent(distributorId)}&firmId=${encodeURIComponent(firmId)}`;
      console.log("📡 Fetching areas from:", url);

      const res = await fetch(url);
      const result = await res.json();

      console.log("📥 Areas API response:", result);

      if (res.ok && result.success) {
        // Get the areas array from the response
        let areasData = result.areas || [];

        // If areasData is empty, check if there's a nested structure
        if (areasData.length === 0 && result.data && result.data.areas) {
          areasData = result.data.areas;
        }

        // Check if the response already contains mapped areas with value/label
        if (areasData.length > 0 && areasData[0].value !== undefined && areasData[0].label !== undefined) {
          // Already in the correct format, just filter out any undefined values
          const validAreas = areasData.filter(area => area.value !== undefined && area.label !== undefined);
          console.log("✅ Areas already in correct format:", validAreas);
          setAreaOptions(validAreas);
          return;
        }

        // Map the areas to the format needed for dropdown
        const mappedAreas = areasData
          .filter(area => area) // Remove null/undefined
          .map(area => {
            // Try multiple possible field names
            const value = area.areaCode || area.code || area._id || area.id || area.value || "";
            const label = area.areaName || area.name || area.label || area.areaCode || area.code || "";

            return {
              value: String(value).trim(),
              label: String(label).trim()
            };
          })
          .filter(area => area.value && area.label); // Remove empty entries

        console.log("✅ Mapped areas:", mappedAreas);
        setAreaOptions(mappedAreas);
      } else {
        console.warn("⚠️ No areas found or API error:", result.message);
        setAreaOptions([]);
      }
    } catch (error) {
      console.error("❌ Failed to load areas:", error);
      setAreaOptions([]);
    }
  };
