  const parseSignedAmount = (value) => {
    const cleanedValue = String(value ?? "")
      .replace(/,/g, "")
      .replace(/\s/g, "")
      .trim();

    if (
      cleanedValue === "" ||
      cleanedValue === "+" ||
      cleanedValue === "-"
    ) {
      return 0;
    }

    const numericValue = Number(cleanedValue);

    return Number.isFinite(numericValue)
      ? numericValue
      : 0;
  };

