  /*
   * Actual commercial net before Credit Note.
   *
   * This already includes:
   * Gross
   * - TPR
   * - Scheme
   * - Star
   * - Cash Discount
   * + GST
   * - Display
   * - Coupon
   * + Add/Less
   */
  const invoiceNetBeforeCreditNote =
    invoiceRound(
      Number(
        invoiceSummary.originalNet || 0
      )
    );

  /*
   * Final payable after Credit Note.
   */
  const invoiceNetPayable =
    invoiceRound(
      Math.max(
        0,
        invoiceNetBeforeCreditNote -
        Number(
          invoiceSummary.creditNote || 0
        )
      )
    );


