  const focusPurchaseProductRow = (rowIndex) => {
    window.requestAnimationFrame(() => {
      window.setTimeout(() => {
        const productInput = document.querySelector(
          `[data-purchase-product-index="${rowIndex}"]`
        );

        if (productInput) {
          productInput.focus();

          productInput.scrollIntoView({
            behavior: "smooth",
            block: "nearest",
            inline: "nearest",
          });
        }
      }, 100);
    });
  };

  const handleAddPurchaseProduct = (event) => {
    if (event) {
      event.preventDefault();
      event.stopPropagation();
    }

    const targetRowIndex =
      currentPurchaseProductIndex >= 0
        ? currentPurchaseProductIndex
        : purchaseActiveRow >= 0
          ? purchaseActiveRow
          : 0;

    const returnContext = {
      returnTo: "Purchase",
      masterType: "Product",
      productRowIndex: targetRowIndex,
    };

    /*
      Keep the context in both ref and state.
      The ref updates immediately and prevents losing the
      return destination during Product Master navigation.
    */
    masterReturnContextRef.current = returnContext;
    setMasterReturnContext(returnContext);

    setShowPurchaseProductList(false);
    setPurchaseProductListFilter("");
    setPurchaseProductDropdownIndex(-1);

    setCurrentPurchaseProductIndex(targetRowIndex);
    setPurchaseActiveRow(targetRowIndex);

    /*
      Use your existing Product Master opening function.
      This does not reset Purchase form data or Purchase items.
    */
    handlePlusClick("Product", event);
  };

  const returnToPurchaseInvoice = async ({
    savedCode = "",
    savedName = "",
  } = {}) => {
    const returnContext =
      masterReturnContextRef.current ||
      masterReturnContext;

    if (returnContext?.returnTo !== "Purchase") {
      return false;
    }

    try {
      const wasEditing =
        Boolean(editProductId);

      /*
        Refresh Product Master data so the newly created
        product becomes available immediately.
      */
      await loadProducts();
      const refreshPage =
        wasEditing
          ? productCurrentPage
          : 1;

      setProductCurrentPage(
        refreshPage
      );

      await loadProductMaster({
        page: refreshPage,
        limit: productRowsPerPage,
        search: productBackendSearch,
        companyCode:
          productCompanyFilter,
        groupCode:
          productGroupFilter,
        categoryCode:
          productCategoryFilter,
      });
    } catch (error) {
      console.error(
        "Unable to refresh Purchase product list:",
        error
      );
    }

    const targetRowIndex =
      Number(returnContext.productRowIndex) >= 0
        ? Number(returnContext.productRowIndex)
        : 0;



    setEditProductId(null);

    setShowSalesList(false);
    setShowPurchaseList(false);
    setShowCreditNoteList(false);
    setShowDebitNoteList(false);
    setShowCreateLoadList(false);
    setShowPrintPreview(false);

    setActiveMenu("vouchers");
    setActiveSubMenu("Purchase");
    setOpenFormFor("Purchase");
    setShowDashboard(false);

    setPurchaseActiveRow(targetRowIndex);
    setCurrentPurchaseProductIndex(targetRowIndex);

    setShowPurchaseProductList(false);
    setPurchaseProductListFilter("");
    setPurchaseProductDropdownIndex(-1);

    /*
      Clear return context only after Purchase is reopened.
    */
    masterReturnContextRef.current = null;
    setMasterReturnContext(null);

    focusPurchaseProductRow(targetRowIndex);

    return true;
  };


