  const updateSettleLoadItem = (index, field, value) => {
    const currentItem = settleLoadItems[index];

    if (!currentItem) return;

    const originalBillAmount = Number(
      currentItem.originalBillAmount ??
      currentItem.BillAmount ??
      currentItem.billAmount ??
      0
    );

    let updatedItems = settleLoadItems.map((item, itemIndex) => {
      if (itemIndex !== index) return item;

      /*
      * PENDING
      * Bill keeps its original amount.
      * It becomes available for the next Create Load,
      * but only after Save Settle Load.
      */
      if (field === "pending") {
        const makePending = value === "Y";

        return {
          ...item,

          originalBillAmount,

          billAmount: originalBillAmount,
          receiptAmount: makePending
            ? 0
            : Number(item.receiptAmount || 0),

          pendingAmount: makePending
            ? originalBillAmount
            : Math.max(
              originalBillAmount -
              Number(item.receiptAmount || 0),
              0
            ),

          pending: makePending ? "Y" : "N",
          cancel: "N",
          adjust: "N",

          transferToNextLoad: makePending,

          status: makePending
            ? "Pending"
            : Number(item.receiptAmount || 0) > 0
              ? "Partial"
              : "Pending",

          receiptSeries: makePending
            ? ""
            : item.receiptSeries || "",

          receiptNo: makePending
            ? ""
            : item.receiptNo || "",

          receiptMode: makePending
            ? ""
            : item.receiptMode || "",
        };
      }

      /*
      * CANCEL
      * Set bill amount, receipt and pending amount to zero.
      * No backend API is called here.
      */
      if (field === "cancel") {
        const makeCancelled = value === "Y";

        if (makeCancelled) {
          return {
            ...item,

            originalBillAmount,

            billAmount: 0,
            receiptAmount: 0,
            pendingAmount: 0,

            cancel: "Y",
            pending: "N",
            adjust: "N",

            transferToNextLoad: false,
            status: "Cancelled",

            receiptSeries: "",
            receiptNo: "",
            receiptMode: "",
            bankCash: "",
            bankName: "",
            chequeNo: "",
            chequeDate: "",
            micr: "",
            transactionNo: "",
          };
        }

        return {
          ...item,

          billAmount: originalBillAmount,
          receiptAmount: 0,
          pendingAmount: originalBillAmount,

          cancel: "N",
          pending: "N",
          adjust: "N",

          transferToNextLoad: false,
          status: "Pending",
        };
      }

      /*
      * ADJUST
      * Adjust remains temporary until Settle Load is saved.
      */
      if (field === "adjust") {
        const makeAdjusted = value === "Y";

        return {
          ...item,

          originalBillAmount,

          billAmount: originalBillAmount,

          receiptAmount: makeAdjusted
            ? originalBillAmount
            : 0,

          pendingAmount: makeAdjusted
            ? 0
            : originalBillAmount,

          adjust: makeAdjusted ? "Y" : "N",
          pending: "N",
          cancel: "N",

          transferToNextLoad: false,

          status: makeAdjusted
            ? "Adjusted"
            : "Pending",
        };
      }

      /*
      * BILL TYPE / OTHER GRID FIELDS
      * These also remain local until Save Settle Load.
      */
      return {
        ...item,
        [field]: value,
      };
    });

    setSettleLoadItems(updatedItems);
    calculateSettleLoadSummary(updatedItems);
  };
