  // Add this function near other validation functions (around line 2000-2100)

  // Validate customer/party before allowing billing
  const validatePartyForBilling = (partyCode, partyName) => {
    // Find the account
    const account = accounts.find(
      acc => acc.accountCode === partyCode || acc.accountName === partyName
    );

    if (!account) {
      return { valid: true, message: '' };
    }

    // Check if blacklisted
    const isBlacklisted =
      String(
        account.blackListed || "NO"
      )
        .trim()
        .toUpperCase() === "YES" ||
      String(
        account.blackListed || ""
      )
        .trim()
        .toUpperCase() === "Y";

    const allowBlacklistParty =
      runtimeGeneralSetup
        ?.billAllowBlacklistParty === true;

    const selectedPartyCode = String(
      account.accountCode ||
      partyCode ||
      ""
    ).trim();

    const isEditingSameOriginalParty =
      Boolean(editingInvoiceId) &&
      selectedPartyCode !== "" &&
      selectedPartyCode ===
      String(
        originalEditingPartyCode || ""
      ).trim();

    if (
      isBlacklisted &&
      !allowBlacklistParty &&
      !isEditingSameOriginalParty
    ) {
      return {
        valid: false,

        message:
          `Party "${account.accountName}" is blacklisted. ` +
          `New billing or changing an existing bill to this party is not allowed.`,
      };
    }

    // Get today's date
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    // Get all sales bills for this party
    const partyBills = salesListData.filter(
      bill => bill.partyCode === partyCode || bill.party === partyName
    );

    // Get pending bills (not settled, not cancelled, not receipt)
    const pendingBills = partyBills.filter(
      bill =>
        bill.status !== 'Settled' &&
        bill.status !== 'Receipt' &&
        bill.status !== 'Cancelled' &&
        bill.status !== 'Cancel'
    );

    // Check CREDIT DAYS - If any pending bill exceeds credit days
    if (account.creditDays && Number(account.creditDays) > 0) {
      const creditDays = Number(account.creditDays);

      for (const bill of pendingBills) {
        const billDate = bill.billDate || bill.BillDate || bill.date;
        if (billDate) {
          const lastDate = new Date(billDate);
          lastDate.setHours(0, 0, 0, 0);
          const diffDays = Math.floor((today - lastDate) / (1000 * 60 * 60 * 24));

          if (diffDays > creditDays) {
            return {
              valid: false,
              message: `🔒 Party "${account.accountName}" has pending bill dated ${billDate} (${diffDays} days old). Credit Days limit is ${creditDays} days. Cannot create new bill.`
            };
          }
        }
      }
    }

    // Check LOCK DAYS - Same as Credit Days logic
    if (account.lockDays && Number(account.lockDays) > 0) {
      const lockDays = Number(account.lockDays);

      for (const bill of pendingBills) {
        const billDate = bill.billDate || bill.BillDate || bill.date;
        if (billDate) {
          const lastDate = new Date(billDate);
          lastDate.setHours(0, 0, 0, 0);
          const diffDays = Math.floor((today - lastDate) / (1000 * 60 * 60 * 24));

          if (diffDays > lockDays) {
            return {
              valid: false,
              message: `🔒 Party "${account.accountName}" has pending bill dated ${billDate} (${diffDays} days old). Lock Days limit is ${lockDays} days. Cannot create new bill.`
            };
          }
        }
      }
    }

    // Check CREDIT BILLS - Count pending credit bills
    if (account.creditBills && Number(account.creditBills) > 0) {
      const creditBillsLimit = Number(account.creditBills);

      const pendingCreditBills = pendingBills.filter(
        bill => bill.billType === 'Credit' || bill.BillType === 'Credit'
      );

      if (pendingCreditBills.length >= creditBillsLimit) {
        return {
          valid: false,
          message: `📋 Party "${account.accountName}" has reached credit bills limit (${creditBillsLimit}). Currently ${pendingCreditBills.length} pending credit bill(s). Cannot create new credit bill.`
        };
      }
    }

    // Check CREDIT AMOUNT limit
    if (account.creditAmt && Number(account.creditAmt) > 0) {
      const creditLimit = Number(account.creditAmt);

      const pendingAmount = pendingBills
        .filter(bill => bill.billType === 'Credit' || bill.BillType === 'Credit')
        .reduce((sum, bill) => sum + Number(bill.amount || bill.NetAmount || 0), 0);

      if (pendingAmount >= creditLimit) {
        return {
          valid: false,
          message: `💰 Party "${account.accountName}" has reached credit limit (₹${creditLimit.toFixed(2)}). Pending credit amount: ₹${pendingAmount.toFixed(2)}. Cannot create new credit bill.`
        };
      }
    }

    return { valid: true, message: '' };
  };


