  const getLoadTransferBillId = (bill = {}) =>
    String(
      bill.SalesBillId ||
      bill.salesBillId ||
      bill._id ||
      bill.id ||
      ""
    ).trim();


  const loadTransferNumber = (value) => {
    const number = Number(value || 0);

    return Number.isFinite(number)
      ? number
      : 0;
  };


  const formatLoadTransferAmount = (value) =>
    loadTransferNumber(value).toLocaleString(
      "en-IN",
      {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
      }
    );


  const formatLoadTransferDate = (value) => {
    if (!value) {
      return "";
    }

    const rawValue =
      String(value).trim();

    /*
     * Handle YYYY-MM-DD directly without timezone conversion.
     */
    const isoDateMatch =
      rawValue.match(
        /^(\d{4})-(\d{2})-(\d{2})/
      );

    if (isoDateMatch) {
      return `${isoDateMatch[3]}/${isoDateMatch[2]}/${isoDateMatch[1]}`;
    }

    const date =
      new Date(rawValue);

    if (
      Number.isNaN(
        date.getTime()
      )
    ) {
      return rawValue;
    }

    return date.toLocaleDateString(
      "en-GB"
    );
  };


