  const handleBillPrintInputChange = (event) => {
    const { name, value } = event.target;

    let normalizedValue = value;

    /*
    * Series values are shown in uppercase in the input,
    * while backend lookup will remain case-insensitive.
    */
    if (
      name === "LoadSeries" ||
      name === "TrnSeries"
    ) {
      normalizedValue = String(value || "").toUpperCase();
    }

    if (
      name === "loadNo" ||
      name === "FromTrnNo" ||
      name === "ToTrnNo"
    ) {
      normalizedValue = String(value || "").replace(
        /[^\d]/g,
        ""
      );
    }

    if (name === "NoOfCopies") {
      normalizedValue =
        value === ""
          ? ""
          : String(
            Math.min(
              10,
              Math.max(1, Number(value || 1))
            )
          );
    }

    const updatedForm = {
      ...billPrintFormData,
      [name]: normalizedValue,
    };

    if (name === "PaperSize") {
      updatedForm.PaperSize =
        String(normalizedValue).toUpperCase() === "A5"
          ? "A5"
          : "A4";

      updatedForm.Orientation =
        updatedForm.PaperSize === "A5"
          ? "landscape"
          : "portrait";
    }

    /*
    * Do not clear TrnSeries/FromTrnNo/ToTrnNo here.
    *
    * This allows the user to enter or override the
    * transaction range manually.
    */
    if (
      name === "LoadSeries" ||
      name === "loadNo"
    ) {
      setBillPrintData(null);
      setShowBillPrintPreview(false);
      setBillPrintError("");
    }

    if (
      name === "TrnSeries" ||
      name === "FromTrnNo" ||
      name === "ToTrnNo"
    ) {
      setBillPrintData(null);
      setShowBillPrintPreview(false);
      setBillPrintError("");
    }

    setBillPrintFormData(updatedForm);

    const persistentFields = [
      "NoOfCopies",
      "GoodsReturn",
      "DamageReturn",
      "SchemeSummary",
      "VatSummary",
      "HSNSummary",
      "PaperSize",
      "Orientation",
    ];

    if (persistentFields.includes(name)) {
      saveBillPrintSettingsLocally(updatedForm);

      window.clearTimeout(
        window.billPrintSettingsTimer
      );

      window.billPrintSettingsTimer =
        window.setTimeout(() => {
          saveBillPrintSettings(updatedForm).catch(
            (error) => {
              console.warn(
                "Automatic Bill Print settings save failed:",
                error
              );
            }
          );
        }, 350);
    }
  };
