  const deleteFirm = async (firm) => {
    const id = firm._id || firm.id;
    if (!id) return alert("Firm ID not found");

    if (!window.confirm(`Delete firm "${firm.firmName}"?`)) return;

    try {
      const response = await fetch(`${API_URL}/firms/${id}`, {
        method: "DELETE"
      });

      const result = await response.json();

      if (!response.ok || !result.success) {
        return alert(result.message || "Firm delete failed");
      }

      /*
 * When deleting the only row on a page,
 * return to the previous valid page.
 */
      const pageAfterDelete =
        firms.length === 1 &&
          firmCurrentPage > 1
          ? firmCurrentPage - 1
          : firmCurrentPage;

      setFirmCurrentPage(pageAfterDelete);

      await loadFirms({
        page: pageAfterDelete,
        limit: firmRowsPerPage,
        search: firmBackendSearch,
      });
      alert("Firm deleted successfully!");
    } catch (error) {
      console.error(error);
      alert("Server not connected. Firm delete failed.");
    }
  };
