  const loadUsers = useCallback(
    async ({
      page = userCurrentPage,
      limit = userRowsPerPage,
      search = userBackendSearch,
    } = {}) => {
      try {
        const distributorId =
          localStorage.getItem("distributorId");

        const firmId =
          localStorage.getItem("firmId");

        if (!distributorId || !firmId) {
          setUsers([]);
          setUserTotalRecords(0);
          setUserTotalPages(1);
          setUserStartRecord(0);
          setUserEndRecord(0);
          return;
        }

        setUserLoading(true);

        const query = new URLSearchParams({
          distributorId,
          firmId,
          page: String(page),
          limit: String(limit),
        });

        const cleanSearch = String(
          search || ""
        ).trim();

        if (cleanSearch) {
          query.set("search", cleanSearch);
        }

        const response = await fetch(
          `${API_URL}/users?${query.toString()}`
        );

        const result = await response.json();

        if (
          !response.ok ||
          result.success === false
        ) {
          throw new Error(
            result.message ||
            "Failed to load users"
          );
        }

        const pagination =
          result.pagination || {};

        const returnedPage = Number(
          pagination.currentPage ||
          pagination.page ||
          page ||
          1
        );

        setUsers(
          Array.isArray(result.users)
            ? result.users
            : []
        );

        setUserCurrentPage(returnedPage);

        setUserRowsPerPage(
          Number(
            pagination.limit ||
            limit ||
            10
          )
        );

        setUserTotalRecords(
          Number(
            pagination.totalRecords ||
            0
          )
        );

        setUserTotalPages(
          Math.max(
            Number(
              pagination.totalPages ||
              1
            ),
            1
          )
        );

        setUserStartRecord(
          Number(
            pagination.startRecord ||
            0
          )
        );

        setUserEndRecord(
          Number(
            pagination.endRecord ||
            0
          )
        );
      } catch (error) {
        console.error(
          "User Master load error:",
          error
        );

        setUsers([]);
        setUserTotalRecords(0);
        setUserTotalPages(1);
        setUserStartRecord(0);
        setUserEndRecord(0);

        alert(
          error.message ||
          "Unable to load users."
        );
      } finally {
        setUserLoading(false);
      }
    },
    [
      userCurrentPage,
      userRowsPerPage,
      userBackendSearch,
    ]
  );

