  const saveUser = async (e) => {
    e.preventDefault();

    if (!userData.userName) return alert("User Name is required");
    if (!userData.password) return alert("Password is required");
    if (userData.password !== userData.reEnterPassword) {
      return alert("Password and Re-enter Password do not match");
    }

    const distributorId = localStorage.getItem("distributorId");
    const firmId = localStorage.getItem("firmId");
    const firmName = localStorage.getItem("firmName");

    const url = editUserId
      ? `${API_URL}/users/${editUserId}`
      : `${API_URL}/users`;

    const method = editUserId ? "PUT" : "POST";

    const res = await fetch(url, {
      method,
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        distributorId,
        firmId,
        firmName,
        userName: userData.userName.trim(),
        oldPassword: userData.oldPassword || "",
        password: userData.password,
        role: "USER",
      }),
    });

    const result = await res.json();

    if (!res.ok || !result.success) {
      return alert(result.message || "User save failed");
    }

    const refreshPage = editUserId
      ? userCurrentPage
      : 1;

    setUserCurrentPage(refreshPage);

    await loadUsers({
      page: refreshPage,
      limit: userRowsPerPage,
      search: userBackendSearch,
    });
    alert(editUserId ? "User updated successfully!" : "User created successfully!");

    // ✅ RESET FORM
    setEditUserId(null);
    setUserData({
      userName: "",
      oldPassword: "",
      password: "",
      reEnterPassword: "",
    });

    // ✅ CLOSE FORM AND SHOW GRID VIEW
    closeForm();
  };
