  const loadInvoiceMappingsByCompany = async (
    selectedCompanyCode
  ) => {
    try {
      const {
        distributorId,
        firmId,
      } = getFirmSession();

      if (!distributorId || !firmId) {
        setInvoiceAreaPartyMappings([]);
        setInvoiceSalesmanAreaMappings([]);
        return;
      }

      const companyCode = String(
        selectedCompanyCode || ""
      ).trim();

      /*
       * MIX mode:
       * Do not send companyCode.
       * Backend will return mappings for all companies.
       */
      const useAllCompanies =
        isMixCompany(companyCode) &&
        runtimeGeneralSetup.allowMixBilling === true;

      /*
       * No company selected:
       * Clear mapping dropdowns.
       */
      if (!companyCode) {
        setInvoiceAreaPartyMappings([]);
        setInvoiceSalesmanAreaMappings([]);
        return;
      }

      const partyQuery =
        new URLSearchParams({
          distributorId,
          firmId,
        });

      const salesmanQuery =
        new URLSearchParams({
          distributorId,
          firmId,
        });

      /*
       * Add companyCode only for a normal company.
       * Never send companyCode=MIX.
       */
      if (!useAllCompanies) {
        partyQuery.set(
          "companyCode",
          companyCode
        );

        salesmanQuery.set(
          "companyCode",
          companyCode
        );
      }

      const [partyResponse, salesmanResponse] =
        await Promise.all([
          fetch(
            `${API_URL}/area-to-party-mappings?${partyQuery.toString()}`
          ),

          fetch(
            `${API_URL}/salesman-area-mappings?${salesmanQuery.toString()}`
          ),
        ]);

      const partyResult =
        await partyResponse.json();

      const salesmanResult =
        await salesmanResponse.json();

      if (
        !partyResponse.ok ||
        partyResult.success === false
      ) {
        throw new Error(
          partyResult.message ||
          "Unable to load Area and Party mappings."
        );
      }

      if (
        !salesmanResponse.ok ||
        salesmanResult.success === false
      ) {
        throw new Error(
          salesmanResult.message ||
          "Unable to load Salesman mappings."
        );
      }

      const partyMappings = Array.isArray(
        partyResult.mappings
      )
        ? partyResult.mappings
        : [];

      const salesmanMappings = Array.isArray(
        salesmanResult.mappings
      )
        ? salesmanResult.mappings
        : [];

      /*
       * Remove duplicate records that can occur in MIX mode.
       */
      const uniquePartyMappings =
        Array.from(
          new Map(
            partyMappings.map((mapping) => [
              [
                mapping.companyCode || "",
                mapping.areaCode || "",
                mapping.accountCode || "",
              ].join("|"),
              mapping,
            ])
          ).values()
        );

      const uniqueSalesmanMappings =
        Array.from(
          new Map(
            salesmanMappings.map((mapping) => [
              [
                mapping.companyCode || "",
                mapping.areaCode || "",
                mapping.salesmanCode || "",
              ].join("|"),
              mapping,
            ])
          ).values()
        );

      setInvoiceAreaPartyMappings(
        uniquePartyMappings
      );

      setInvoiceSalesmanAreaMappings(
        uniqueSalesmanMappings
      );
    } catch (error) {
      console.error(
        "Invoice mapping load error:",
        error
      );

      setInvoiceAreaPartyMappings([]);
      setInvoiceSalesmanAreaMappings([]);
    }
  };
