  // Load Credit Note bills from database
  const loadCreditNoteBills = async () => {
    try {
      const { distributorId, firmId } = getFirmSession();

      if (!distributorId || !firmId) {
        setCreditNoteListData([]);
        return;
      }

      const res = await fetch(
        `${API_URL}/credit-note?distributorId=${distributorId}&firmId=${firmId}`
      );

      const result = await res.json();

      if (!res.ok || !result.success) {
        alert(result.message || "Failed to load credit notes");
        return;
      }

      setCreditNoteListData(result.creditNotes || []);
    } catch (error) {
      console.error("Credit note list load error:", error);
    }
  };
  const loadNextCreditNoteBillNo = async (series = "") => {
    try {
      // Do not generate another number while editing a Credit Note
      if (editingCreditNoteId) return;

      const { distributorId, firmId } = getFirmSession();

      if (!distributorId || !firmId) return;

      const res = await fetch(
        `${API_URL}/credit-note/next-bill-no` +
        `?distributorId=${encodeURIComponent(distributorId)}` +
        `&firmId=${encodeURIComponent(firmId)}` +
        `&creditNoteSeries=${encodeURIComponent(series || "")}`
      );

      const result = await res.json();

      if (res.ok && result.success) {
        setCreditNoteFormData((prev) => ({
          ...prev,
          creditNoteNo: result.nextCreditNoteNo || "",
        }));
      }
    } catch (error) {
      console.error("Next Credit Note number error:", error);
    }
  };

  useEffect(() => {
    if (
      openFormFor === "Credit Note" &&
      !editingCreditNoteId
    ) {
      loadNextCreditNoteBillNo(
        creditNoteFormData.creditNoteSeries
      );
    }
  }, [
    creditNoteFormData.creditNoteSeries,
    openFormFor,
    editingCreditNoteId,
  ]);
  const findCreditCompany = (companyValue) => {
    const selectedValue = String(
      typeof companyValue === "object"
        ? companyValue?.companyCode ||
        companyValue?.CompanyCode ||
        companyValue?.code ||
        companyValue?.Code ||
        companyValue?.companyName ||
        companyValue?.CompanyName ||
        companyValue?.name ||
        companyValue?.Name ||
        companyValue?._id ||
        companyValue?.id ||
        ""
        : companyValue || ""
    )
      .trim()
      .toUpperCase();

    if (!selectedValue) {
      return null;
    }

    return (
      companies.find((company) => {
        const companyValues = [
          company?._id,
          company?.id,

          company?.companyCode,
          company?.CompanyCode,
          company?.code,
          company?.Code,

          company?.companyName,
          company?.CompanyName,
          company?.name,
          company?.Name,
        ]
          .map((value) =>
            String(value ?? "")
              .trim()
              .toUpperCase()
          )
          .filter(Boolean);

        return companyValues.includes(selectedValue);
      }) || null
    );
  };

  const getCreditCompanyCode = (companyValue) => {
    const company =
      findCreditCompany(companyValue);

    return String(
      company?.companyCode ||
      company?.CompanyCode ||
      company?.code ||
      company?.Code ||
      ""
    ).trim();
  };

  const getCreditCompanyName = (companyValue) => {
    const company =
      findCreditCompany(companyValue);

    return String(
      company?.companyName ||
      company?.CompanyName ||
      company?.name ||
      company?.Name ||
      ""
    ).trim();
  };

  const loadCreditNotePartiesByCompany =
    async (companyValue) => {
      try {
        const {
          distributorId,
          firmId,
        } = getFirmSession();

        if (!distributorId || !firmId) {
          setInvoiceAreaPartyMappings([]);
          return;
        }

        const companyCode =
          getCreditCompanyCode(companyValue);

        if (!companyCode) {
          setInvoiceAreaPartyMappings([]);
          return;
        }

        const params = new URLSearchParams({
          distributorId:
            String(distributorId),

          firmId:
            String(firmId),

          companyCode,
        });

        const response = await fetch(
          `${API_URL}/area-to-party-mappings?${params.toString()}`
        );

        const result = await response.json();

        if (
          response.ok &&
          result.success &&
          Array.isArray(result.mappings)
        ) {
          setInvoiceAreaPartyMappings(
            result.mappings
          );

          return result.mappings;
        }

        setInvoiceAreaPartyMappings([]);

        return [];
      } catch (error) {
        console.error(
          "Credit Note party mapping load error:",
          error
        );

        setInvoiceAreaPartyMappings([]);

        return [];
      }
    };

  const loadSalesBillForCreditNote = useCallback(
    async (formValues = null) => {
      const currentForm =
        formValues || creditNoteFormData;

      const billSeries = String(
        currentForm.billSeries || ""
      ).trim();

      const billNo = String(
        currentForm.billNo || ""
      ).trim();

      if (!billNo) {
        setCreditBillLoadMessage("");
        return;
      }

      try {
        const {
          distributorId,
          firmId,
        } = getFirmSession();

        if (!distributorId || !firmId) {
          setCreditBillLoadMessage(
            "Distributor or firm information is missing."
          );
          return;
        }

        if (creditBillRequestRef.current) {
          creditBillRequestRef.current.abort();
        }

        const controller = new AbortController();

        creditBillRequestRef.current =
          controller;

        setCreditBillLoading(true);
        setCreditBillLoadMessage(
          "Loading bill details..."
        );

        /*
         * Do not force the currently selected company into
         * the bill lookup. The referenced bill itself will
         * supply the correct company.
         */
        const params = new URLSearchParams({
          distributorId: String(distributorId),
          firmId: String(firmId),
          billSeries,
          billNo,
        });

        const response = await fetch(
          `${API_URL}/sales/find-bill?${params.toString()}`,
          {
            signal: controller.signal,
          }
        );

        const result = await response.json();

        if (!response.ok || !result.success) {
          setCreditBillLoadMessage(
            result.message ||
            "Sales bill not found."
          );

          setCreditNoteItems([]);
          calcCreditNoteSummary([]);

          setCreditNoteSummary((previous) => ({
            ...previous,
            billBalAmt: 0,
          }));

          return;
        }

        const bill =
          result.bill ||
          result.sale ||
          result.salesBill ||
          result.data ||
          {};

        const loadedBillSeries = String(
          bill.BillSeries ??
          bill.billSeries ??
          bill.Series ??
          bill.series ??
          billSeries
        ).trim();

        const loadedBillNo = String(
          bill.BillNo ??
          bill.billNo ??
          bill.BillNumber ??
          bill.billNumber ??
          billNo
        ).trim();

        const partyCode = String(
          bill.PartyCode ??
          bill.partyCode ??
          bill.SysAcCode ??
          ""
        ).trim();

        const partyName = String(
          bill.PartyName ??
          bill.partyName ??
          bill.party ??
          ""
        ).trim();

        const companyCode = String(
          bill.CompanyCode ??
          bill.companyCode ??
          bill.Company ??
          bill.company ??
          ""
        ).trim();

        const companyName = String(
          bill.CompanyName ??
          bill.companyName ??
          getCreditCompanyName(companyCode) ??
          companyCode
        ).trim();

        const salesmanCode = String(
          bill.SalesmanCode ??
          bill.salesmanCode ??
          ""
        ).trim();

        const salesmanName = String(
          bill.SalesmanName ??
          bill.salesmanName ??
          bill.salesman ??
          ""
        ).trim();

        const godownCode = String(
          bill.GDCode ??
          bill.GodownCode ??
          bill.godownCode ??
          bill.Godown ??
          bill.godown ??
          "G1"
        ).trim();

        const billAmount = creditNumber(
          bill.OriginalNetAmount ??
          bill.originalNetAmount ??
          bill.NetAmount ??
          bill.netAmount ??
          bill.NetAmt ??
          bill.netAmt ??
          bill.amount
        );

        const previousCreditAmount =
          creditNumber(
            bill.CreditNoteAmount ??
            bill.creditNoteAmount
          );

        const outstandingAmount =
          creditNumber(
            bill.BalanceAmount ??
            bill.balanceAmount ??
            bill.OutstandingAmount ??
            bill.outstandingAmount ??
            Math.max(
              0,
              billAmount - previousCreditAmount
            )
          );

        const sourceItems = Array.isArray(
          bill.items
        )
          ? bill.items
          : Array.isArray(bill.Items)
            ? bill.Items
            : Array.isArray(bill.products)
              ? bill.products
              : Array.isArray(
                result.items
              )
                ? result.items
                : [];

        /*
         * Convert Sales Invoice products to Credit Note rows.
         * Batch is stored internally, but there is no Batch
         * column in the Credit Note grid.
         */
        const loadedCreditItems =
          sourceItems.map((sourceItem, index) => {
            /*
       * Read Product Code from all possible old and new
       * Sales Bill item field names.
        */
            const rawProductCode = String(
              sourceItem.productCode ??
              sourceItem.ProductCode ??
              sourceItem.ProdCode ??
              sourceItem.prodCode ??
              sourceItem.itemCode ??
              sourceItem.ItemCode ??
              sourceItem.code ??
              sourceItem.Code ??
              sourceItem.product?.productCode ??
              sourceItem.product?.ProductCode ??
              sourceItem.product?.ProdCode ??
              ""
            ).trim();

            /*
             * productId can sometimes contain the Product Master MongoDB
             * _id instead of the actual product code.
             */
            const rawProductId = String(
              sourceItem.productId?._id ??
              sourceItem.productId ??
              sourceItem.ProductId?._id ??
              sourceItem.ProductId ??
              sourceItem.product?._id ??
              sourceItem.product?.id ??
              ""
            ).trim();

            const normalizeCreditProductValue = (value) =>
              String(value ?? "")
                .trim()
                .toLowerCase();

            /*
             * Find the matching Product Master using either:
             * 1. Product Code
             * 2. Product Master _id/id
             * 3. Old product-code field names
             */
            const matchedProduct = products.find((product) => {
              const masterIds = [
                product._id,
                product.id,
                product.productId,
                product.ProductId,
              ]
                .map(normalizeCreditProductValue)
                .filter(Boolean);

              const masterCodes = [
                product.productCode,
                product.ProductCode,
                product.ProdCode,
                product.prodCode,
                product.itemCode,
                product.ItemCode,
                product.code,
                product.Code,
                typeof getProductCode === "function"
                  ? getProductCode(product)
                  : "",
              ]
                .map(normalizeCreditProductValue)
                .filter(Boolean);

              const billCode =
                normalizeCreditProductValue(rawProductCode);

              const billProductId =
                normalizeCreditProductValue(rawProductId);

              return (
                (billCode && masterCodes.includes(billCode)) ||
                (billProductId &&
                  (
                    masterIds.includes(billProductId) ||
                    masterCodes.includes(billProductId)
                  ))
              );
            });

            /*
             * Use the real Product Code from Product Master when the
             * bill contains only productId.
             */
            const productCode = String(
              rawProductCode ||
              matchedProduct?.productCode ||
              matchedProduct?.ProductCode ||
              matchedProduct?.ProdCode ||
              matchedProduct?.prodCode ||
              matchedProduct?.itemCode ||
              matchedProduct?.code ||
              (
                typeof getProductCode === "function"
                  ? getProductCode(matchedProduct)
                  : ""
              ) ||
              rawProductId ||
              ""
            ).trim();

            /*
             * First use the name saved in the bill.
             * If it is missing, obtain it from Product Master.
             */
            const productName = String(
              sourceItem.productName ??
              sourceItem.ProductName ??
              sourceItem.ProdName ??
              sourceItem.prodName ??
              sourceItem.itemName ??
              sourceItem.ItemName ??
              sourceItem.name ??
              sourceItem.Name ??
              sourceItem.product?.productName ??
              sourceItem.product?.ProductName ??
              sourceItem.product?.ProdName ??
              matchedProduct?.productName ??
              matchedProduct?.ProductName ??
              matchedProduct?.ProdName ??
              matchedProduct?.prodName ??
              matchedProduct?.itemName ??
              matchedProduct?.name ??
              (
                typeof getProductName === "function"
                  ? getProductName(matchedProduct)
                  : ""
              ) ??
              ""
            ).trim();

            const batchNo = String(
              sourceItem.batchNo ??
              sourceItem.BatchNo ??
              sourceItem.Batch ??
              sourceItem.batch ??
              sourceItem.selectedBatch
                ?.batchNo ??
              sourceItem.selectedBatch?.Batch ??
              "."
            ).trim() || ".";

            const qty = creditNumber(
              sourceItem.qty ??
              sourceItem.Qty ??
              sourceItem.quantity
            );

            const free = creditNumber(
              sourceItem.free ??
              sourceItem.Free
            );

            const mrp = creditNumber(
              sourceItem.mrp ??
              sourceItem.MRP ??
              sourceItem.selectedBatch?.mrp ??
              sourceItem.selectedBatch?.MRP
            );

            const rate = creditNumber(
              sourceItem.rate ??
              sourceItem.Rate ??
              sourceItem.salesRate ??
              sourceItem.SRate
            );

            const gstPercent = creditNumber(
              sourceItem.gstPercent ??
              sourceItem.GSTPercent ??
              sourceItem.gst ??
              sourceItem.GST
            );

            const loadedRow = {
              id:
                sourceItem._id ||
                sourceItem.id ||
                `credit-${Date.now()}-${index}`,

              sr: index + 1,
              trn: "GDR",

              productId:
                sourceItem.productId ||
                sourceItem._id ||
                productCode,

              productCode,
              itemCode: productCode,
              itemName: productName,

              batchNo,

              selectedBatch: {
                batchNo,
                Batch: batchNo,
                mrp,
                MRP: mrp,
                salesRate: rate,
                SRate: rate,
                stockQty: creditNumber(
                  sourceItem.stockQty ??
                  sourceItem.StockQty
                ),
              },

              hsn: String(
                sourceItem.hsn ??
                sourceItem.HSN ??
                sourceItem.hsnCode ??
                sourceItem.HSNCode ??
                matchedProduct?.hsn ??
                matchedProduct?.HSN ??
                matchedProduct?.hsnCode ??
                matchedProduct?.HSNCode ??
                ""
              ),

              unit: String(
                sourceItem.unit ??
                sourceItem.Unit ??
                sourceItem.basicUnit ??
                sourceItem.BasicUnit ??
                matchedProduct?.basicUnit ??
                matchedProduct?.BasicUnit ??
                matchedProduct?.unit ??
                matchedProduct?.Unit ??
                "PCS"
              ),

              boxPack: creditNumber(
                sourceItem.boxPack ??
                sourceItem.BoxPack ??
                matchedProduct?.boxPack ??
                matchedProduct?.BoxPack ??
                1
              ),

              inboxPack: creditNumber(
                sourceItem.inboxPack ??
                sourceItem.InBoxPack ??
                sourceItem.InboxPack ??
                matchedProduct?.inboxPack ??
                matchedProduct?.InBoxPack ??
                matchedProduct?.InboxPack ??
                1
              ),

              qty,
              free,
              mrp,
              rate,

              grossAmt: "",

              schPercent: creditNumber(
                sourceItem.schPercent ??
                sourceItem.schemePercent ??
                sourceItem.SchemePercent
              ),

              schAmt: creditNumber(
                sourceItem.schAmt ??
                sourceItem.schemeAmount ??
                sourceItem.SchemeAmount
              ),

              tprPercent: creditNumber(
                sourceItem.tprPercent ??
                sourceItem.TPRPercent
              ),

              tprAmt: creditNumber(
                sourceItem.tprAmt ??
                sourceItem.TPRAmount
              ),

              cdPercent: creditNumber(
                sourceItem.cdPercent ??
                sourceItem.cashDiscountPercent ??
                sourceItem.CashDiscountPercent
              ),

              cdAmt: creditNumber(
                sourceItem.cdAmt ??
                sourceItem.cashDiscountAmount ??
                sourceItem.CashDiscountAmount
              ),

              starPercent: creditNumber(
                sourceItem.starPercent ??
                sourceItem.StarPercent
              ),

              starAmt: creditNumber(
                sourceItem.starAmt ??
                sourceItem.StarAmount
              ),

              gstPercent,

              cessPercent: creditNumber(
                sourceItem.cessPercent ??
                sourceItem.CessPercent ??
                0
              ),
            };

            return calculateCreditNoteRow(
              loadedRow
            );
          });

        setCreditNoteFormData((previous) => ({
          ...previous,

          billSeries: loadedBillSeries,
          billNo: loadedBillNo,

          party: partyName,
          partyName,
          partyCode,

          company: companyCode,
          companyCode,
          companyName,

          godown: godownCode,

          salesman: salesmanName,
          salesmanCode,

          tinNo: String(
            bill.TinNo ??
            bill.tinNo ??
            bill.GSTNo ??
            bill.gstNo ??
            ""
          ),

          refBy:
            loadedBillSeries && loadedBillNo
              ? `${loadedBillSeries}-${loadedBillNo}`
              : loadedBillNo,

          refDate:
            bill.BillDate ??
            bill.billDate ??
            previous.refDate,

          narr:
            previous.narr &&
              previous.narr !== "Credit Note"
              ? previous.narr
              : `Credit Note against Bill ${loadedBillSeries
                ? `${loadedBillSeries}-`
                : ""
              }${loadedBillNo}`,
        }));

        /*
         * This is the missing part in your old function.
         */
        setCreditNoteItems(
          loadedCreditItems
        );

        setCreditNoteActiveRow(
          loadedCreditItems.length > 0
            ? 0
            : -1
        );

        setCurrentCreditProductIndex(-1);
        setShowCreditProductList(false);
        setCreditFilteredProductList([]);

        calcCreditNoteSummary(
          loadedCreditItems
        );

        setCreditNoteSummary((previous) => ({
          ...previous,
          billBalAmt:
            outstandingAmount.toFixed(2),
        }));

        /*
         * Refresh party mapping for the bill company.
         */
        if (companyCode) {
          loadCreditNotePartiesByCompany(
            companyCode
          );
        }

        setCreditBillLoadMessage(
          `${loadedCreditItems.length} product${loadedCreditItems.length === 1
            ? ""
            : "s"
          } loaded — ₹${outstandingAmount.toLocaleString(
            "en-IN",
            {
              minimumFractionDigits: 2,
              maximumFractionDigits: 2,
            }
          )} outstanding`
        );
      } catch (error) {
        if (error.name === "AbortError") {
          return;
        }

        console.error(
          "Sales bill load for Credit Note failed:",
          error
        );

        setCreditBillLoadMessage(
          "Unable to load bill. Please check the server."
        );
      } finally {
        setCreditBillLoading(false);
      }
    },
    [creditNoteFormData, products, companies]
  );


  /*
    Automatically reload the referenced sales bill whenever
    Bill Series or Bill No changes.
  */
  useEffect(() => {
    if (openFormFor !== "Credit Note") {
      return undefined;
    }

    const billNo = String(
      creditNoteFormData.billNo || ""
    ).trim();

    if (!billNo) {
      setCreditBillLoadMessage("");
      return undefined;
    }

    const timer = window.setTimeout(() => {
      loadSalesBillForCreditNote({
        ...creditNoteFormData,
      });
    }, 150);

    return () => {
      window.clearTimeout(timer);
    };
  }, [
    openFormFor,
    creditNoteFormData.billSeries,
    creditNoteFormData.billNo,
  ]);
  const saveCreditNote = async () => {
    try {
      const {
        distributorId,
        firmId,
        firmName,
      } = getFirmSession();

      if (
        !distributorId ||
        !firmId
      ) {
        alert(
          "Distributor/Firm not found. Please login again."
        );

        return;
      }

      if (!creditNoteFormData.party) {
        alert(
          "Please select a party."
        );

        return;
      }

      if (!creditNoteFormData.company) {
        alert(
          "Please select a company."
        );

        return;
      }

      const validItems =
        creditNoteItems.filter(
          (item) =>
            String(
              item.itemCode ||
              item.productCode ||
              ""
            ).trim() &&
            (
              Number(item.qty || 0) +
              Number(item.free || 0)
            ) > 0
        );

      if (
        validItems.length === 0
      ) {
        alert(
          "Please add at least one product with quantity."
        );

        return;
      }

      const invalidItemIndex =
        validItems.findIndex(
          (item) =>
            !String(
              item.batchNo ||
              item.selectedBatch?.batchNo ||
              item.selectedBatch?.Batch ||
              "."
            ).trim() ||
            Number(
              item.mrp ??
              item.selectedBatch?.mrp ??
              item.selectedBatch?.MRP ??
              0
            ) < 0
        );

      if (
        invalidItemIndex >= 0
      ) {
        alert(
          `Please select a valid batch and MRP in row ${invalidItemIndex + 1
          }.`
        );

        return;
      }

      const godownCode = String(
        creditNoteFormData.godownCode ||
        creditNoteFormData.gdCode ||
        creditNoteFormData.godown ||
        ""
      ).trim();

      if (!godownCode) {
        alert(
          "Please select a valid godown."
        );

        return;
      }

      const totalTaxableValue =
        validItems.reduce(
          (total, item) =>
            total +
            Number(
              item.taxable ??
              item.taxableValue ??
              0
            ),
          0
        );

      const totalCgst =
        validItems.reduce(
          (total, item) =>
            total +
            Number(item.cgst || 0),
          0
        );

      const totalSgst =
        validItems.reduce(
          (total, item) =>
            total +
            Number(item.sgst || 0),
          0
        );

      const totalIgst =
        validItems.reduce(
          (total, item) =>
            total +
            Number(item.igst || 0),
          0
        );

      const creditNoteData = {
        distributorId,
        firmId,

        firmName:
          firmName ||
          localStorage.getItem(
            "firmName"
          ) ||
          "",

        VDate:
          creditNoteFormData.vDate,

        CreditNoteSeries:
          creditNoteFormData.creditNoteSeries ||
          "CN",

        CreditNoteNo:
          Number(
            creditNoteFormData.creditNoteNo ||
            0
          ),

        BillSeries:
          creditNoteFormData.billSeries ||
          "",

        BillNo:
          Number(
            creditNoteFormData.billNo ||
            0
          ),

        PartyCode:
          creditNoteFormData.partyCode ||
          creditNoteFormData.party ||
          "",

        PartyName:
          creditNoteFormData.partyName ||
          creditNoteFormData.party ||
          "",

        Godown:
          creditNoteFormData.godownName ||
          creditNoteFormData.godown ||
          "",

        GDCode:
          godownCode,

        CompanyCode:
          creditNoteFormData.companyCode ||
          creditNoteFormData.company ||
          "",

        CompanyName:
          creditNoteFormData.companyName ||
          creditNoteFormData.company ||
          "",

        SalesmanCode:
          creditNoteFormData.salesmanCode ||
          "",

        SalesmanName:
          creditNoteFormData.salesmanName ||
          creditNoteFormData.salesman ||
          "",

        RefBy:
          creditNoteFormData.refBy ||
          "",

        RefDate:
          creditNoteFormData.refDate ||
          "",

        Narration:
          creditNoteFormData.narr ||
          "",

        GrossAmount:
          Number(
            creditNoteSummary.grossAmt ||
            0
          ),

        SchemeAmount:
          Number(
            creditNoteSummary.schemeAmt ||
            0
          ),

        TPRAmount:
          Number(
            creditNoteSummary.tprAmt ||
            0
          ),

        CashDiscountAmount:
          Number(
            creditNoteSummary.cashDisc ||
            0
          ),

        StarDiscountAmount:
          Number(
            creditNoteSummary.starAmt ||
            0
          ),

        DisplayAmount:
          Number(
            creditNoteSummary.display ||
            0
          ),

        CouponAmount:
          Number(
            creditNoteSummary.coupon ||
            0
          ),

        AddLessAmount:
          Number(
            creditNoteSummary.addLess ||
            0
          ),

        TaxableValue:
          totalTaxableValue,

        GSTAmount:
          Number(
            creditNoteSummary.gstAmt ||
            0
          ),

        CGSTAmount:
          totalCgst,

        SGSTAmount:
          totalSgst,

        IGSTAmount:
          totalIgst,

        NetAmount:
          Number(
            creditNoteSummary.netAmt ||
            0
          ),

        TotalQty:
          validItems.reduce(
            (total, item) =>
              total +
              Number(item.qty || 0),
            0
          ),

        TotalFreeQty:
          validItems.reduce(
            (total, item) =>
              total +
              Number(item.free || 0),
            0
          ),

        TotalItems:
          validItems.length,

        items:
          validItems.map(
            (item, index) => {
              const selectedBatch =
                item.selectedBatch ||
                {};

              return {
                Sr:
                  index + 1,

                TRN:
                  String(
                    item.trn ||
                    "GDR"
                  )
                    .trim()
                    .toUpperCase(),

                ProductCode:
                  item.itemCode ||
                  item.productCode ||
                  "",

                ProductName:
                  item.itemName ||
                  item.productName ||
                  "",

                Batch:
                  item.batchNo ||
                  selectedBatch.batchNo ||
                  selectedBatch.Batch ||
                  ".",

                MRP:
                  Number(
                    item.mrp ??
                    selectedBatch.mrp ??
                    selectedBatch.MRP ??
                    0
                  ),

                Unit:
                  item.unit ||
                  "PCS",

                Qty:
                  Number(
                    item.qty ||
                    0
                  ),

                Free:
                  Number(
                    item.free ||
                    0
                  ),

                Rate:
                  Number(
                    item.rate ??
                    item.salesRate ??
                    selectedBatch.salesRate ??
                    selectedBatch.SRate ??
                    0
                  ),

                SRate:
                  Number(
                    item.salesRate ??
                    item.rate ??
                    selectedBatch.salesRate ??
                    selectedBatch.SRate ??
                    0
                  ),

                PRate:
                  Number(
                    item.purchaseRate ??
                    selectedBatch.purchaseRate ??
                    selectedBatch.PRate ??
                    0
                  ),

                BoxPack:
                  Number(
                    item.boxPack ??
                    selectedBatch.boxPack ??
                    selectedBatch.BoxPack ??
                    1
                  ) || 1,

                InBoxPack:
                  Number(
                    item.inboxPack ??
                    selectedBatch.inboxPack ??
                    selectedBatch.InBoxPack ??
                    1
                  ) || 1,

                GrossAmount:
                  Number(
                    item.grossAmt ||
                    0
                  ),

                SchemePercent:
                  Number(
                    item.schPercent ||
                    0
                  ),

                SchemeAmount:
                  Number(
                    item.schAmt ||
                    0
                  ),

                TPRPercent:
                  Number(
                    item.tprPercent ||
                    0
                  ),

                TPRAmount:
                  Number(
                    item.tprAmt ||
                    0
                  ),

                CashDiscountPercent:
                  Number(
                    item.cdPercent ||
                    0
                  ),

                CashDiscountAmount:
                  Number(
                    item.cdAmt ||
                    0
                  ),

                StarPercent:
                  Number(
                    item.starPercent ||
                    0
                  ),

                StarAmount:
                  Number(
                    item.starAmt ||
                    0
                  ),

                TaxableValue:
                  Number(
                    item.taxable ||
                    0
                  ),

                GSTPercent:
                  Number(
                    item.gstPercent ||
                    0
                  ),

                GSTAmount:
                  Number(
                    item.gstAmt ||
                    item.gstArt ||
                    0
                  ),

                CGST:
                  Number(
                    item.cgst ||
                    0
                  ),

                SGST:
                  Number(
                    item.sgst ||
                    0
                  ),

                IGST:
                  Number(
                    item.igst ||
                    0
                  ),

                CessPercent:
                  Number(
                    item.cessPercent ||
                    0
                  ),

                CessAmount:
                  Number(
                    item.cessAmt ||
                    0
                  ),
              };
            }
          ),

        amount:
          Number(
            creditNoteSummary.netAmt ||
            0
          ),

        Status:
          "Approved",

        CreatedBy:
          localStorage.getItem(
            "userName"
          ) ||
          "ADMIN",

        UpdatedBy:
          localStorage.getItem(
            "userName"
          ) ||
          "ADMIN",
      };

      const isEditing =
        Boolean(
          editingCreditNoteId
        );

      const requestUrl =
        isEditing
          ? `${API_URL}/credit-note/${encodeURIComponent(
            editingCreditNoteId
          )}`
          : `${API_URL}/credit-note`;

      const response =
        await fetch(
          requestUrl,
          {
            method:
              isEditing
                ? "PUT"
                : "POST",

            headers: {
              "Content-Type":
                "application/json",
            },

            body:
              JSON.stringify(
                creditNoteData
              ),
          }
        );

      const result =
        await response.json();

      if (
        !response.ok ||
        !result.success
      ) {
        throw new Error(
          result.message ||
          (
            isEditing
              ? "Credit Note update failed."
              : "Credit Note save failed."
          )
        );
      }

      if (
        typeof loadSalesBills ===
        "function"
      ) {
        await loadSalesBills();
      }

      if (
        typeof loadStock ===
        "function"
      ) {
        await loadStock();
      }

      if (
        typeof loadProducts ===
        "function"
      ) {
        await loadProducts();
      }

      const savedCreditNoteAmount =
        Number(
          result.data?.NetAmount ??
          result.data?.amount ??
          creditNoteSummary.netAmt ??
          0
        );

      setEditingCreditNoteId(
        null
      );

      /*
       * When the Credit Note was opened from
       * an unsaved Sales Invoice, return there.
       */
      if (
        creditNoteReturnToBilling
      ) {
        alert(
          isEditing
            ? "Credit Note updated successfully!"
            : "Credit Note saved successfully!"
        );

        returnFromCreditNoteToBilling({
          saved:
            true,

          creditNoteAmount:
            savedCreditNoteAmount,
        });

        return;
      }

      /*
       * Normal menu-based Credit Note:
       * clear form and open list.
       */
      setCreditNoteItems([]);
      setCreditNoteActiveRow(-1);
      setCurrentCreditProductIndex(-1);
      setCreditProductListFilter("");
      setShowCreditProductList(false);

      setCreditNoteCurrentPage(
        1
      );

      setListPage(
        (previous) => ({
          ...previous,
          "Credit Note": 1,
        })
      );

      await loadCreditNotes({
        page: 1,

        limit:
          creditNoteRowsPerPage,

        filters:
          creditNoteAppliedFilters,

        search:
          creditNoteSearchDebounced,
      });

      setOpenFormFor(null);
      setShowCreditNoteList(true);
      setShowPurchaseList(false);
      setShowDebitNoteList(false);
      setShowSalesList(false);

      setActiveMenu(
        "vouchers"
      );

      setActiveSubMenu(
        "Credit Note"
      );

      setShowDashboard(false);

      alert(
        isEditing
          ? "Credit Note updated successfully!"
          : "Credit Note saved successfully!"
      );

      /*
       * Do not call closeForm() here.
       * It can hide the Credit Note list.
       */
    } catch (error) {
      console.error(
        "Credit Note save error:",
        error
      );

      alert(
        error.message ||
        "Server not connected. Credit Note was not saved."
      );
    }
  };
  const deleteCreditNote = async (
    creditNoteRow
  ) => {
    try {
      const creditNoteId =
        creditNoteRow?._id ||
        creditNoteRow?.id ||
        creditNoteRow
          ?.originalItem?._id ||
        "";

      if (!creditNoteId) {
        alert(
          "Credit Note ID was not found."
        );

        return;
      }

      const confirmed =
        window.confirm(
          `Delete Credit Note ${creditNoteRow.billSeries ||
          ""
          }-${creditNoteRow.billNo ||
          ""
          }?\n\nStock and linked Sales Bill values will be reversed.`
        );

      if (!confirmed) {
        return;
      }

      const {
        distributorId,
        firmId,
      } = getFirmSession();

      if (
        !distributorId ||
        !firmId
      ) {
        alert(
          "Distributor/Firm not found."
        );

        return;
      }

      const response = await fetch(
        `${API_URL}/credit-note/${encodeURIComponent(
          creditNoteId
        )}`,
        {
          method: "DELETE",

          headers: {
            "Content-Type":
              "application/json",
          },

          body:
            JSON.stringify({
              distributorId,
              firmId,
            }),
        }
      );

      const result =
        await response.json();

      if (
        !response.ok ||
        !result.success
      ) {
        throw new Error(
          result.message ||
          "Credit Note delete failed."
        );
      }

      alert(
        result.message ||
        "Credit Note deleted successfully."
      );

      const targetPage =
        creditNoteListData.length === 1 &&
          creditNoteCurrentPage > 1
          ? creditNoteCurrentPage - 1
          : creditNoteCurrentPage;

      setCreditNoteCurrentPage(
        targetPage
      );

      setListPage(
        (previous) => ({
          ...previous,
          "Credit Note":
            targetPage,
        })
      );

      await loadCreditNotes({
        page:
          targetPage,

        limit:
          creditNoteRowsPerPage,

        filters:
          creditNoteAppliedFilters,

        search:
          creditNoteSearchDebounced,
      });

      if (
        typeof loadStock ===
        "function"
      ) {
        await loadStock();
      }

      if (
        typeof loadSalesBills ===
        "function"
      ) {
        await loadSalesBills();
      }
    } catch (error) {
      console.error(
        "Credit Note delete error:",
        error
      );

      alert(
        error.message ||
        "Unable to delete Credit Note."
      );
    }
  };
  const handleDebitNoteInputChange = (e) => {
    const { name, value } = e.target;
    setDebitNoteFormData({ ...debitNoteFormData, [name]: regexInputValue(name, value) });
  };

  const addDebitNoteItem = useCallback(() => {
    const newItem = {
      id: Date.now(),
      sr: debitNoteItems.length + 1,
      trn: 'DGR',
      itemCode: '',
      itemName: '',
      unit: 'PCS',
      qty: '',
      free: '',
      rate: '',
      grossAmt: '',
      bvDisc1: '',
      bvDisc2: '',
      bvAdd1: '',
      bvAdd2: '',
      taxable: '',
      gstPercent: '',
      gstArt: '',
      avDisc1: '',
      avDisc2: '',
      cgst: '',
      sgst: '',
      igst: '',
      cessPercent: '',
      cessAmt: '',
      cessPerP: ''
    };
    setDebitNoteItems([...debitNoteItems, newItem]);
    setDebitNoteActiveRow(debitNoteItems.length);
  }, [debitNoteItems.length]);

  const updateDebitNoteItem = (index, field, value) => {
    const newItems = [...debitNoteItems];
    newItems[index][field] = value;

    if (field === 'qty' && value) {
      const item = newItems[index];
      const qty = parseFloat(value) || 0;
      const rate = parseFloat(item.rate) || 0;
      const grossAmt = qty * rate;
      item.grossAmt = grossAmt.toFixed(2);

      let afterDisc1 = grossAmt;
      if (parseFloat(item.bvDisc1)) {
        const disc1Amt = grossAmt * (parseFloat(item.bvDisc1) / 100);
        afterDisc1 = grossAmt - disc1Amt;
      }

      let afterDisc2 = afterDisc1;
      if (parseFloat(item.bvDisc2)) {
        const disc2Amt = afterDisc1 * (parseFloat(item.bvDisc2) / 100);
        afterDisc2 = afterDisc1 - disc2Amt;
      }

      let afterAdd1 = afterDisc2;
      if (parseFloat(item.bvAdd1)) {
        afterAdd1 = afterDisc2 + (grossAmt * parseFloat(item.bvAdd1) / 100);
      }

      let afterAdd2 = afterAdd1;
      if (parseFloat(item.bvAdd2)) {
        afterAdd2 = afterAdd1 + (grossAmt * parseFloat(item.bvAdd2) / 100);
      }

      item.taxable = afterAdd2.toFixed(2);

      if (parseFloat(item.gstPercent)) {
        const gstAmt = afterAdd2 * (parseFloat(item.gstPercent) / 100);
        item.gstArt = gstAmt.toFixed(2);
        const halfGst = (gstAmt / 2).toFixed(2);
        if (debitNoteFormData.igst === 'Y') {
          item.igst = gstAmt.toFixed(2);
        } else {
          item.cgst = halfGst;
          item.sgst = halfGst;
        }
      }

      calcDebitNoteSummary(newItems);

      // Add new row when qty is entered and it's the last row

    } else if (field === 'rate' && value) {
      const item = newItems[index];
      const qty = parseFloat(item.qty) || 0;
      const rate = parseFloat(value) || 0;
      const grossAmt = qty * rate;
      item.grossAmt = grossAmt.toFixed(2);

      let afterDisc1 = grossAmt;
      if (parseFloat(item.bvDisc1)) {
        const disc1Amt = grossAmt * (parseFloat(item.bvDisc1) / 100);
        afterDisc1 = grossAmt - disc1Amt;
      }

      let afterDisc2 = afterDisc1;
      if (parseFloat(item.bvDisc2)) {
        const disc2Amt = afterDisc1 * (parseFloat(item.bvDisc2) / 100);
        afterDisc2 = afterDisc1 - disc2Amt;
      }

      let afterAdd1 = afterDisc2;
      if (parseFloat(item.bvAdd1)) {
        afterAdd1 = afterDisc2 + (grossAmt * parseFloat(item.bvAdd1) / 100);
      }

      let afterAdd2 = afterAdd1;
      if (parseFloat(item.bvAdd2)) {
        afterAdd2 = afterAdd1 + (grossAmt * parseFloat(item.bvAdd2) / 100);
      }

      item.taxable = afterAdd2.toFixed(2);

      if (parseFloat(item.gstPercent)) {
        const gstAmt = afterAdd2 * (parseFloat(item.gstPercent) / 100);
        item.gstArt = gstAmt.toFixed(2);
        const halfGst = (gstAmt / 2).toFixed(2);
        if (debitNoteFormData.igst === 'Y') {
          item.igst = gstAmt.toFixed(2);
        } else {
          item.cgst = halfGst;
          item.sgst = halfGst;
        }
      }

      calcDebitNoteSummary(newItems);
    } else if (field === 'bvDisc1' && value) {
      const item = newItems[index];
      const grossAmt = parseFloat(item.grossAmt) || 0;
      const disc1Amt = grossAmt * (parseFloat(value) / 100);
      const afterDisc1 = grossAmt - disc1Amt;
      let afterDisc2 = afterDisc1;
      if (parseFloat(item.bvDisc2)) {
        const disc2Amt = afterDisc1 * (parseFloat(item.bvDisc2) / 100);
        afterDisc2 = afterDisc1 - disc2Amt;
      }
      let afterAdd1 = afterDisc2;
      if (parseFloat(item.bvAdd1)) {
        afterAdd1 = afterDisc2 + (grossAmt * parseFloat(item.bvAdd1) / 100);
      }
      let afterAdd2 = afterAdd1;
      if (parseFloat(item.bvAdd2)) {
        afterAdd2 = afterAdd1 + (grossAmt * parseFloat(item.bvAdd2) / 100);
      }
      item.taxable = afterAdd2.toFixed(2);
      if (parseFloat(item.gstPercent)) {
        const gstAmt = afterAdd2 * (parseFloat(item.gstPercent) / 100);
        item.gstArt = gstAmt.toFixed(2);
      }
      calcDebitNoteSummary(newItems);
    } else if (field === 'gstPercent' && value) {
      const item = newItems[index];
      const taxable = parseFloat(item.taxable) || 0;
      const gstAmt = taxable * (parseFloat(value) / 100);
      item.gstArt = gstAmt.toFixed(2);
      const halfGst = (gstAmt / 2).toFixed(2);
      if (debitNoteFormData.igst === 'Y') {
        item.igst = gstAmt.toFixed(2);
      } else {
        item.cgst = halfGst;
        item.sgst = halfGst;
      }
      calcDebitNoteSummary(newItems);
    }

    /*
 * Recalculate whenever these fields change
 * from Batch Selection or Manual Entry.
 */
    if (
      [
        "mrp",
        "rate",
        "purchaseRate",
        "stockQty",
        "gstPercent",
        "qty",
        "bvDisc1",
        "bvDisc2",
        "bvAdd1",
        "bvAdd2",
      ].includes(field)
    ) {
      const item = newItems[index];

      const qty = parseFloat(item.qty) || 0;
      const rate = parseFloat(item.rate) || 0;

      const grossAmt = qty * rate;
      item.grossAmt = grossAmt.toFixed(2);

      let afterDisc1 = grossAmt;

      if (parseFloat(item.bvDisc1)) {
        afterDisc1 =
          grossAmt -
          (grossAmt * parseFloat(item.bvDisc1)) / 100;
      }

      let afterDisc2 = afterDisc1;

      if (parseFloat(item.bvDisc2)) {
        afterDisc2 =
          afterDisc1 -
          (afterDisc1 * parseFloat(item.bvDisc2)) / 100;
      }

      let afterAdd1 = afterDisc2;

      if (parseFloat(item.bvAdd1)) {
        afterAdd1 =
          afterDisc2 +
          (grossAmt * parseFloat(item.bvAdd1)) / 100;
      }

      let afterAdd2 = afterAdd1;

      if (parseFloat(item.bvAdd2)) {
        afterAdd2 =
          afterAdd1 +
          (grossAmt * parseFloat(item.bvAdd2)) / 100;
      }

      item.taxable = afterAdd2.toFixed(2);

      const gstPercent =
        parseFloat(item.gstPercent) || 0;

      const gstAmt =
        afterAdd2 * gstPercent / 100;

      item.gstArt = gstAmt.toFixed(2);

      if (debitNoteFormData.igst === "Y") {
        item.igst = gstAmt.toFixed(2);
        item.cgst = "0.00";
        item.sgst = "0.00";
      } else {
        item.igst = "0.00";
        item.cgst = (gstAmt / 2).toFixed(2);
        item.sgst = (gstAmt / 2).toFixed(2);
      }

      calcDebitNoteSummary(newItems);
    }
    const shouldAddNextRow =
      field === "qty" &&
      Number(value || 0) > 0 &&
      index === newItems.length - 1;

    if (shouldAddNextRow) {
      const nextRowIndex =
        newItems.length;

      const newDebitRow = {
        id: `debit-row-${Date.now()}-${nextRowIndex}`,
        sr: nextRowIndex + 1,

        trn: "DGR",

        productId: "",
        productCode: "",
        itemCode: "",
        itemName: "",

        selectedBatch: null,
        batchNo: "",

        hsn: "",
        unit: "PCS",

        qty: "",
        free: "",

        mrp: "",
        rate: "",
        salesRate: "",
        purchaseRate: "",
        stockQty: 0,

        grossAmt: "0.00",

        bvDisc1: "",
        bvDisc2: "",
        bvAdd1: "",
        bvAdd2: "",

        taxable: "0.00",

        gstPercent: "",
        gstArt: "0.00",

        avDisc1: "",
        avDisc2: "",

        cgst: "0.00",
        sgst: "0.00",
        igst: "0.00",

        cessPercent: "",
        cessAmt: "0.00",
        cessPerP: "",
      };

      const itemsWithNewRow = [
        ...newItems,
        newDebitRow,
      ];

      setDebitNoteItems(
        itemsWithNewRow
      );

      calcDebitNoteSummary(
        itemsWithNewRow
      );

      setDebitNoteActiveRow(
        index
      );



      return;
    }

    setDebitNoteItems(newItems);
    setDebitNoteActiveRow(index);
  };

  const deleteDebitNoteItem = (index) => {
    const newItems = debitNoteItems.filter((_, i) => i !== index);
    newItems.forEach((item, i) => { item.sr = i + 1; });
    setDebitNoteItems(newItems);
    calcDebitNoteSummary(newItems);
  };

  const calcDebitNoteSummary = (currentItems) => {
    let grossAmt = 0, gstAmt = 0;
    currentItems.forEach(item => {
      grossAmt += parseFloat(item.grossAmt || 0);
      gstAmt += parseFloat(item.gstArt || 0);
    });
    const netAmt = grossAmt + gstAmt;
    setDebitNoteSummary({
      ...debitNoteSummary,
      grossAmt,
      gstAmt,
      netAmt: netAmt.toFixed(2),
      beforeVatDiscAmt: grossAmt,
      afterVatDiscAmt: grossAmt,
      tcsAmt: 0
    });
  };

  const handleDebitNoteKeyDown = (e, index, field) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      const fields = ['trn', 'itemCode', 'itemName', 'unit', 'qty', 'free', 'rate', 'bvDisc1', 'bvDisc2', 'bvAdd1', 'bvAdd2', 'gstPercent'];
      const nextFieldIndex = fields.indexOf(field) + 1;
      if (nextFieldIndex < fields.length) {
        const nextInput = document.querySelector(`[data-debit-field="${fields[nextFieldIndex]}"][data-debit-index="${index}"]`);
        nextInput?.focus();
      } else {
        const nextProduct = document.querySelector(`[data-debit-product-index="${index + 1}"]`);
        if (nextProduct) {
          nextProduct.focus();
        } else {
          addDebitNoteItem();
          setTimeout(() => {
            const nextProductInput = document.querySelector(`[data-debit-product-index="${index + 1}"]`);
            if (nextProductInput) nextProductInput.focus();
          }, 100);
        }
      }
    }
  };

  const handleDebitProductClick = (index) => {
    setCurrentDebitProductIndex(index);
    setDebitProductListFilter('');
    setShowDebitProductList(true);
  };

  const handleDebitProductSelect = async (
    index,
    selectedEntry
  ) => {
    if (
      index < 0 ||
      !selectedEntry
    ) {
      return;
    }

    const product =
      selectedEntry.product ||
      selectedEntry;

    const productCode = String(
      getProductCode(product) ||
      product.productCode ||
      product.ProductCode ||
      product.ProdCode ||
      product.prodCode ||
      product.itemCode ||
      product.ItemCode ||
      product.code ||
      product.Code ||
      ""
    ).trim();

    const productName = String(
      product.productName ||
      product.ProductName ||
      product.ProdName ||
      product.prodName ||
      product.itemName ||
      product.ItemName ||
      product.name ||
      product.Name ||
      (
        typeof getProductName === "function"
          ? getProductName(product)
          : ""
      ) ||
      ""
    )
      .replace(
        new RegExp(
          `^${String(productCode)
            .replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\s*[-–—:]?\\s*`,
          "i"
        ),
        ""
      )
      .trim();

    if (!productCode) {
      alert(
        "Selected product code is missing."
      );

      return;
    }

    const selectedRow =
      debitNoteItems[index] || {};

    /*
     * Debit Note default transaction:
     *
     * DGR = Damaged Goods Return
     * GDR = Good Goods Return
     */
    const transactionType = String(
      selectedRow.trn || "DGR"
    )
      .trim()
      .toUpperCase();

    /*
     * Read selected Debit Note godown.
     */
    const selectedGodownValue =
      debitNoteFormData.godownCode ||
      debitNoteFormData.godown ||
      "";

    const matchedGodown =
      godowns.find((godown) => {
        const possibleValues = [
          godown._id,
          godown.id,
          godown.godownCode,
          godown.GodownCode,
          godown.gdCode,
          godown.GDCode,
          godown.code,
          godown.name,
          godown.godownName,
        ]
          .map((value) =>
            String(value || "")
              .trim()
              .toUpperCase()
          )
          .filter(Boolean);

        return possibleValues.includes(
          String(selectedGodownValue)
            .trim()
            .toUpperCase()
        );
      });

    const gdCode = String(
      matchedGodown?.godownCode ||
      matchedGodown?.GodownCode ||
      matchedGodown?.gdCode ||
      matchedGodown?.GDCode ||
      matchedGodown?.code ||
      selectedGodownValue ||
      ""
    ).trim();

    const {
      distributorId,
      firmId,
    } = getFirmSession();

    if (
      !distributorId ||
      !firmId
    ) {
      alert(
        "Distributor/Firm not found. Please login again."
      );

      return;
    }

    const productHsn = String(
      product.hsn ??
      product.HSN ??
      product.hsnCode ??
      product.HSNCode ??
      ""
    ).trim();

    const productUnit = String(
      product.basicUnit ??
      product.BasicUnit ??
      product.unit ??
      product.Unit ??
      "PCS"
    ).trim();

    const productGstPercent = Number(
      product.gstPercent ??
      product.GSTPercent ??
      product.gst ??
      product.GST ??
      product.tax ??
      0
    ) || 0;

    /*
     * Fill only Product Master information first.
     * Batch, MRP, Rate and Stock will come from
     * MAS_STOCK or MAS_DAMSTOCK.
     */
    setDebitNoteItems((previousItems) =>
      previousItems.map((row, rowIndex) => {
        if (rowIndex !== index) {
          return row;
        }

        return {
          ...row,

          productId:
            product._id ||
            product.id ||
            product.productId ||
            productCode,

          productCode,
          itemCode: productCode,
          itemName: productName,

          hsn: productHsn,
          unit: productUnit,
          gstPercent: productGstPercent,

          batchNo: "",
          selectedBatch: null,

          mrp: "",
          rate: "",
          salesRate: "",
          purchaseRate: "",
          stockQty: 0,
        };
      })
    );

    /*
     * Close Product Master dropdown.
     */
    setShowDebitProductList(false);
    setDebitProductListFilter("");
    setDebitFilteredProductList([]);
    setDebitProductDropdownIndex(-1);
    setCurrentDebitProductIndex(-1);

    /*
     * Prepare batch modal.
     */
    setDebitBatchProduct({
      ...product,
      productCode,
      productName,
      hsn: productHsn,
      unit: productUnit,
      gstPercent: productGstPercent,
    });

    setDebitBatchRowIndex(index);

    setDebitBatchTransactionType(
      transactionType
    );

    setDebitBatchRows([]);
    setDebitBatchSelectedIndex(0);
    setDebitBatchLoading(true);
    setShowDebitBatchModal(true);
    window.setTimeout(() => {
      debitBatchModalRef.current?.focus();
    }, 50);

    try {
      const query =
        new URLSearchParams({
          distributorId:
            String(distributorId),

          firmId:
            String(firmId),

          gdCode:
            String(gdCode || ""),

          prodCode:
            productCode,

          trnType:
            transactionType,

          includeLocked:
            "N",
        });

      /*
       * This endpoint already reads:
       * GDR -> MAS_STOCK
       * DGR -> MAS_DAMSTOCK
       */
      const response = await fetch(
        `${API_URL}/stock/credit-note-batches?${query.toString()}`
      );

      const result =
        await response.json();

      if (
        !response.ok ||
        !result.success
      ) {
        throw new Error(
          result.message ||
          "Failed to load Debit Note batches."
        );
      }

      const loadedBatches =
        Array.isArray(result.batches)
          ? result.batches
          : [];

      setDebitBatchRows(
        loadedBatches
      );
      setDebitBatchSelectedIndex(0);

      window.setTimeout(() => {
        debitBatchModalRef.current?.focus();
      }, 0);
    } catch (error) {
      console.error(
        "Debit Note batch load error:",
        error
      );

      setDebitBatchRows([]);

      alert(
        error.message ||
        "Unable to load Debit Note batches."
      );
    } finally {
      setDebitBatchLoading(false);
    }
  };
  const selectDebitNoteBatch = (
    batch
  ) => {
    if (
      debitBatchRowIndex < 0 ||
      !debitBatchProduct ||
      !batch
    ) {
      return;
    }

    const selectedIndex =
      debitBatchRowIndex;

    const product =
      debitBatchProduct;

    const productCode = String(
      getProductCode(product) ||
      product.productCode ||
      product.ProductCode ||
      product.ProdCode ||
      product.code ||
      ""
    ).trim();

    const productName = String(
      getProductName(product) ||
      product.productName ||
      product.ProductName ||
      product.ProdName ||
      product.name ||
      ""
    ).trim();

    const batchNo = String(
      batch.batchNo ||
      batch.BatchNo ||
      batch.Batch ||
      batch.batch ||
      "."
    ).trim() || ".";

    const mrp = Number(
      batch.mrp ??
      batch.MRP ??
      0
    ) || 0;

    const salesRate = Number(
      batch.salesRate ??
      batch.SalesRate ??
      batch.sRate ??
      batch.SRate ??
      batch.rate ??
      batch.Rate ??
      product.salesRate ??
      product.SRate ??
      product.Rate_Per_Unit ??
      0
    ) || 0;

    const purchaseRate = Number(
      batch.purchaseRate ??
      batch.PurchaseRate ??
      batch.pRate ??
      batch.PRate ??
      product.purchaseRate ??
      product.PRate ??
      0
    ) || 0;

    const stockQty = Number(
      batch.stockQty ??
      batch.StockQty ??
      batch.balanceQty ??
      batch.BalanceQty ??
      batch.qty ??
      batch.Qty ??
      0
    ) || 0;

    const gstPercent = Number(
      batch.gstPercent ??
      batch.GSTPercent ??
      product.gstPercent ??
      product.GSTPercent ??
      product.gst ??
      product.GST ??
      product.tax ??
      0
    ) || 0;

    /*
     * For Debit Note manual entry:
     *
     * GDR uses MAS_STOCK.
     * DGR uses MAS_DAMSTOCK.
     *
     * Rate remains SRate, matching the
     * Credit Note batch behavior you requested.
     */
    const debitRate =
      salesRate;

    setDebitNoteItems(
      (previousItems) => {
        const updatedItems =
          previousItems.map(
            (row, rowIndex) => {
              if (
                rowIndex !== selectedIndex
              ) {
                return row;
              }

              return {
                ...row,

                productId:
                  product._id ||
                  product.id ||
                  productCode,

                productCode,
                itemCode:
                  productCode,

                itemName:
                  productName,

                selectedBatch: {
                  ...batch,

                  batchNo,
                  mrp,

                  salesRate,
                  purchaseRate,
                  stockQty,
                },

                batchNo,
                mrp,

                rate:
                  debitRate,

                salesRate,
                purchaseRate,
                stockQty,

                hsn: String(
                  batch.hsn ??
                  batch.HSN ??
                  product.hsn ??
                  product.HSN ??
                  product.hsnCode ??
                  product.HSNCode ??
                  row.hsn ??
                  ""
                ),

                unit: String(
                  batch.unit ??
                  batch.Unit ??
                  product.basicUnit ??
                  product.BasicUnit ??
                  product.unit ??
                  product.Unit ??
                  row.unit ??
                  "PCS"
                ),

                gstPercent,
              };
            }
          );

        window.setTimeout(() => {
          calcDebitNoteSummary(
            updatedItems
          );
        }, 0);

        return updatedItems;
      }
    );

    setShowDebitBatchModal(false);
    setDebitBatchRows([]);
    setDebitBatchProduct(null);
    setDebitBatchRowIndex(-1);
    setDebitBatchSelectedIndex(0);

    window.setTimeout(() => {
      const qtyInput =
        document.querySelector(
          `[data-debit-field="qty"][data-debit-index="${selectedIndex}"]`
        );

      qtyInput?.focus();
      qtyInput?.select();
    }, 60);
  };

  // useEffect(() => {
