  const saveQuotation = async () => {
    try {
      const { distributorId, firmId, firmName } =
        getFirmSession();

      if (!distributorId || !firmId) {
        alert(
          "Distributor/Firm not found. Please login again."
        );
        return;
      }

      const selectedGodown = godowns.find(
        (godown) =>
          String(godown.name || "") ===
          String(invoiceFormData.godown || "") ||
          String(godown.code || "") ===
          String(invoiceFormData.godown || "")
      );

      const selectedCompany = companies.find(
        (company) =>
          String(
            company.name ||
            company.companyName ||
            ""
          ) === String(invoiceFormData.company || "") ||
          String(
            company.code ||
            company.companyCode ||
            ""
          ) === String(invoiceFormData.company || "")
      );

      const selectedParty = accounts.find(
        (account) =>
          String(account.accountName || "") ===
          String(invoiceFormData.party || "") ||
          String(account.accountCode || "") ===
          String(invoiceFormData.party || "")
      );

      const selectedArea = areas.find(
        (area) =>
          String(area.name || area.areaName || "") ===
          String(invoiceFormData.area || "") ||
          String(area.code || area.areaCode || "") ===
          String(invoiceFormData.area || "")
      );

      const selectedSalesman = salesmen.find(
        (salesman) =>
          String(
            salesman.name ||
            salesman.salesmanName ||
            ""
          ) === String(invoiceFormData.salesman || "") ||
          String(
            salesman.code ||
            salesman.salesmanCode ||
            ""
          ) === String(invoiceFormData.salesman || "")
      );

      const validItems = invoiceItems
        .filter(
          (item) =>
            String(
              item.productCode ||
              item.productId ||
              item.product ||
              ""
            ).trim() !== "" &&
            Number(item.qty || item.quantity || 0) > 0
        )
        .map((item, index) => ({
          ...item,

          sr: item.sr || index + 1,

          productCode:
            item.productCode ||
            item.productId ||
            item.code ||
            String(item.product || "").split(" - ")[0] ||
            "",

          productId:
            item.productCode ||
            item.productId ||
            item.code ||
            String(item.product || "").split(" - ")[0] ||
            "",

          productName:
            item.productName ||
            item.name ||
            String(item.product || "")
              .split(" - ")
              .slice(1)
              .join(" - ") ||
            "",

          batchNo:
            item.batchNo ||
            item.batch ||
            item.selectedBatch?.batchNo ||
            ".",

          qty: Number(
            item.qty ||
            item.quantity ||
            0
          ),

          quantity: Number(
            item.qty ||
            item.quantity ||
            0
          ),

          free: Number(item.free || 0),
          mrp: Number(item.mrp || 0),
          rate: Number(item.rate || 0),
          rateGst: Number(item.rateGst || 0),
          tprAmt: Number(item.tprAmt || 0),

          schemePct: Number(item.schemePct || 0),
          schemeAmt: Number(item.schemeAmt || 0),

          cdPct: Number(item.cdPct || 0),
          cdAmt: Number(item.cdAmt || 0),

          starPct: Number(item.starPct || 0),
          starAmt: Number(item.starAmt || 0),

          taxable: Number(item.taxable || 0),
          gst: Number(item.gst || 0),
          sgst: Number(item.sgst || 0),
          cgst: Number(item.cgst || 0),
          igst: Number(item.igst || 0),
          amount: Number(item.amount || 0),
        }));

      if (!invoiceFormData.billNo) {
        alert("Quotation Bill No is required.");
        return;
      }

      if (!invoiceFormData.party) {
        alert("Please select Party.");
        return;
      }

      if (validItems.length === 0) {
        alert(
          "Please add at least one valid product in quotation."
        );
        return;
      }

      /*
        Read manual values directly as a fallback.
  
        This ensures the value entered in Display,
        Coupon and Add/Less is included even if a
        state recalculation is still pending.
      */
      const displayAmount =
        parseSignedAmount(
          invoiceManualAdjustments.display
        ) ||
        Number(invoiceSummary.display || 0);

      const couponAmount =
        parseSignedAmount(
          invoiceManualAdjustments.coupon
        ) ||
        Number(invoiceSummary.coupon || 0);

      const addLessAmount =
        parseSignedAmount(
          invoiceManualAdjustments.addLess
        ) ||
        Number(invoiceSummary.addLess || 0);

      const schemeAmount =
        Number(invoiceSummary.scheme || 0);

      const starAmount =
        Number(invoiceSummary.star || 0);

      const cashDiscountAmount =
        Number(invoiceSummary.cd || 0);

      const taxableValue = Math.max(
        0,
        Number(invoiceSummary.gross || 0) -
        Number(invoiceSummary.tpr || 0) -
        schemeAmount -
        starAmount -
        cashDiscountAmount -
        displayAmount -
        couponAmount
      );

      const gstAmount =
        Number(invoiceSummary.sgst || 0) +
        Number(invoiceSummary.cgst || 0) +
        Number(invoiceSummary.igst || 0);

      const originalNetAmount =
        taxableValue +
        gstAmount +
        addLessAmount;

      const netAmount =
        Math.round(originalNetAmount * 100) / 100;

      const payload = {
        distributorId,
        firmId,
        firmName,

        BillDate:
          invoiceFormData.billDate ||
          new Date().toISOString().split("T")[0],

        Godown:
          selectedGodown?.name ||
          invoiceFormData.godown ||
          "",

        GDCode:
          selectedGodown?.code ||
          invoiceFormData.godown ||
          "",

        CompanyCode:
          selectedCompany?.code ||
          selectedCompany?.companyCode ||
          "",

        CompanyName:
          selectedCompany?.name ||
          selectedCompany?.companyName ||
          invoiceFormData.company ||
          "",

        AreaCode:
          selectedArea?.code ||
          selectedArea?.areaCode ||
          "",

        AreaName:
          selectedArea?.name ||
          selectedArea?.areaName ||
          invoiceFormData.area ||
          "",

        PartyCode:
          selectedParty?.accountCode ||
          invoiceFormData.partyCode ||
          "",

        PartyName:
          selectedParty?.accountName ||
          invoiceFormData.partyName ||
          invoiceFormData.party ||
          "",

        BillSeries:
          invoiceFormData.BillSeries ||
          invoiceFormData.billSeries ||
          "",

        BillNo: Number(invoiceFormData.billNo || 0),

        BillType:
          invoiceFormData.billType || "Credit",

        DueDate: invoiceFormData.dueDate || "",

        SalesmanCode:
          selectedSalesman?.code ||
          selectedSalesman?.salesmanCode ||
          invoiceFormData.salesmanCode ||
          "",

        SalesmanName:
          selectedSalesman?.name ||
          selectedSalesman?.salesmanName ||
          invoiceFormData.salesmanName ||
          invoiceFormData.salesman ||
          "",

        Narration:
          invoiceFormData.narration || "",

        GrossAmount: Number(
          invoiceSummary.gross || 0
        ),

        TPRAmount: Number(
          invoiceSummary.tpr || 0
        ),

        SchemeAmount: schemeAmount,

        StarDiscountAmount: starAmount,

        CashDiscountAmount:
          cashDiscountAmount,

        DisplayAmount: displayAmount,

        CouponAmount: couponAmount,

        AddLessAmount: addLessAmount,

        TaxableValue: taxableValue,

        SGSTAmount: Number(
          invoiceSummary.sgst || 0
        ),

        CGSTAmount: Number(
          invoiceSummary.cgst || 0
        ),

        IGSTAmount: Number(
          invoiceSummary.igst || 0
        ),

        OriginalNetAmount:
          Math.round(originalNetAmount * 100) /
          100,

        NetAmount: netAmount,

        TotalQty: validItems.reduce(
          (sum, item) =>
            sum + Number(item.qty || 0),
          0
        ),

        TotalFreeQty: validItems.reduce(
          (sum, item) =>
            sum + Number(item.free || 0),
          0
        ),

        TotalItems: validItems.length,

        items: validItems,
      };

      console.log(
        "Quotation payload:",
        payload
      );

      const isEditMode =
        Boolean(editingInvoiceId);

      const url = isEditMode
        ? `${API_URL}/quotation/${editingInvoiceId}`
        : `${API_URL}/quotation`;

      const method = isEditMode
        ? "PUT"
        : "POST";

      const res = await fetch(url, {
        method,
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(payload),
      });

      const result = await res.json();

      if (!res.ok || !result.success) {
        alert(
          result.message ||
          "Quotation save failed"
        );
        return;
      }

      alert(
        isEditMode
          ? "Quotation updated successfully!"
          : "Quotation saved successfully!"
      );

      await loadQuotationBills({
        page:
          quotationCurrentPage,

        limit:
          quotationRowsPerPage,

        filters:
          quotationAppliedFilters,

        search:
          quotationSearchDebounced,
      });

      const retainedCompany =
        invoiceFormData.company || "";

      const retainedBillSeries =
        invoiceFormData.BillSeries || "";

      const retainedGodown =
        invoiceFormData.godown || "G1";

      const retainedBillType =
        invoiceFormData.billType || "Credit";

      const nextBillNo =
        result.nextBillNo ||
        Number(invoiceFormData.billNo || 0) + 1;

      resetQuotationForm({
        nextBillNo,
        company: retainedCompany,
        billSeries: retainedBillSeries,
        godown: retainedGodown,
        billType: retainedBillType,
      });
    } catch (error) {
      console.error(
        "Quotation save error:",
        error
      );

      alert(
        "Server not connected. Quotation save failed."
      );
    }
  };
