  const loadOtherAccounts = async () => {
    try {
      const distributorId = localStorage.getItem("distributorId");
      const firmId = localStorage.getItem("firmId");

      if (!distributorId || !firmId) {
        setOtherAccounts([]);
        return;
      }

      const res = await fetch(
        `${API_URL}/other-accounts?distributorId=${distributorId}&firmId=${firmId}`
      );

      const result = await res.json();

      if (!res.ok) {
        return alert(result.message || "Failed to load other accounts");
      }

      setOtherAccounts(
        (result.otherAccounts || []).map((a) => ({
          id: a._id,
          ...a,
        }))
      );
    } catch (error) {
      console.error(error);
    }
  };
  const loadOtherAccountMaster =
    useCallback(
      async ({
        page = 1,
        limit = 20,
        search = "",
      } = {}) => {
        try {
          const distributorId =
            localStorage.getItem(
              "distributorId"
            );

          const firmId =
            localStorage.getItem(
              "firmId"
            );

          if (
            !distributorId ||
            !firmId
          ) {
            setOtherAccountMasterRows(
              []
            );

            setOtherAccountTotalRecords(
              0
            );

            setOtherAccountTotalPages(
              1
            );

            setOtherAccountStartRecord(
              0
            );

            setOtherAccountEndRecord(
              0
            );

            return;
          }

          setOtherAccountLoading(true);

          const params =
            new URLSearchParams({
              distributorId,
              firmId,
              page: String(page),
              limit: String(limit),
            });

          const searchText =
            String(
              search || ""
            ).trim();

          if (searchText) {
            params.set(
              "search",
              searchText
            );
          }

          const response =
            await fetch(
              `${API_URL}/other-accounts/list?${params.toString()}`
            );

          const result =
            await response.json();

          if (
            !response.ok ||
            result.success === false
          ) {
            throw new Error(
              result.message ||
              "Failed to load Other Account Master"
            );
          }

          const pagination =
            result.pagination || {};

          setOtherAccountMasterRows(
            Array.isArray(
              result.otherAccounts
            )
              ? result.otherAccounts
              : []
          );

          setOtherAccountCurrentPage(
            Number(
              pagination.currentPage ||
              page
            )
          );

          setOtherAccountRowsPerPage(
            Number(
              pagination.limit ||
              limit
            )
          );

          setOtherAccountTotalRecords(
            Number(
              pagination.totalRecords ||
              0
            )
          );

          setOtherAccountTotalPages(
            Math.max(
              Number(
                pagination.totalPages ||
                1
              ),
              1
            )
          );

          setOtherAccountStartRecord(
            Number(
              pagination.startRecord ||
              0
            )
          );

          setOtherAccountEndRecord(
            Number(
              pagination.endRecord ||
              0
            )
          );
        } catch (error) {
          console.error(
            "Other Account Master load error:",
            error
          );

          setOtherAccountMasterRows(
            []
          );

          setOtherAccountTotalRecords(
            0
          );

          setOtherAccountTotalPages(
            1
          );

          setOtherAccountStartRecord(
            0
          );

          setOtherAccountEndRecord(
            0
          );

          alert(
            error.message ||
            "Unable to load Other Account Master."
          );
        } finally {
          setOtherAccountLoading(false);
        }
      },
      []
    );

