  // ===== Area To Party Mapping Handlers =====
  const filteredAreasForPartyMapping = areas.filter(area => {
    const areaName = area.name || area.areaName || "";
    const areaCode = area.code || area.areaCode || "";
    return (
      areaName.toLowerCase().includes(areaToPartyFilter.toLowerCase()) ||
      areaCode.toLowerCase().includes(areaToPartyFilter.toLowerCase())
    );
  });

  const getCompanyCode = (company) =>
    company?.companyCode || company?.code || "";

  const getCompanyName = (company) =>
    company?.companyName || company?.name || "";

  const handleAreaToPartyCompanySelect = async (company) => {
    setAreaToPartyCompany(company);
    setAreaToPartyFilter("");
    setAreaToPartyEditingRow(-1);
    setAreaToPartyEditingCell("");
    setShowAreaToPartyDropdown(false);

    if (!company || accounts.length === 0) {
      setAreaToPartyData([]);
      return;
    }

    const baseRows = accounts.map((account, index) => ({
      id: `atp_${index}_${Date.now()}`,
      accountCode: account.accountCode || account.code || "",
      accountName: account.accountName || account.name || "",
      areaCode: "",
      areaName: "",
    }));

    try {
      const distributorId = localStorage.getItem("distributorId");
      const firmId = localStorage.getItem("firmId");

      const res = await fetch(
        `${API_URL}/area-to-party-mappings?distributorId=${distributorId}&firmId=${firmId}&companyCode=${getCompanyCode(company)}`
      );

      const result = await res.json();

      if (!res.ok) {
        setAreaToPartyData(baseRows);
        return;
      }

      const savedMappings = result.mappings || [];

      const mergedRows = baseRows.map((row) => {
        const saved = savedMappings.find(
          (m) => String(m.accountCode) === String(row.accountCode)
        );

        return saved
          ? {
            ...row,
            areaCode: saved.areaCode || "",
            areaName: saved.areaName || "",
          }
          : row;
      });

      setAreaToPartyData(mergedRows);
    } catch (error) {
      console.error(error);
      setAreaToPartyData(baseRows);
    }
  };

  const handleAreaToPartyCellClick = (rowIndex, cellType) => {
    if (cellType !== "areaName") return;

    setAreaToPartyEditingRow(rowIndex);
    setAreaToPartyEditingCell(`areaName_${rowIndex}`);
    setShowAreaToPartyDropdown(true);
    setAreaToPartyFilter("");
  };

  const handleAreaToPartySelect = (rowIndex, selectedArea) => {
    setAreaToPartyData((prev) =>
      prev.map((row, idx) =>
        idx === rowIndex
          ? {
            ...row,
            areaCode: selectedArea.code || selectedArea.areaCode || "",
            areaName: selectedArea.name || selectedArea.areaName || "",
          }
          : row
      )
    );

    setShowAreaToPartyDropdown(false);
    setAreaToPartyEditingRow(-1);
    setAreaToPartyEditingCell("");
    setAreaToPartyFilter("");
  };

  const handleAreaToPartyKeyDown = (e, rowIndex) => {
    if (e.key === "Escape") {
      setShowAreaToPartyDropdown(false);
      setAreaToPartyEditingRow(-1);
      setAreaToPartyEditingCell("");
      setAreaToPartyFilter("");
    }
  };

  const handleAreaToPartyFilterChange = (e) => {
    setAreaToPartyFilter(e.target.value);
  };

  const saveAreaToPartyMapping = async () => {
    if (!areaToPartyCompany) {
      return alert("Please select company");
    }

    const mappedRows = areaToPartyData.filter((row) => row.areaCode);

    if (mappedRows.length === 0) {
      return alert("Please select at least one area");
    }

    const distributorId = localStorage.getItem("distributorId");
    const firmId = localStorage.getItem("firmId");
    const firmName = localStorage.getItem("firmName");

    if (!distributorId || !firmId) {
      return alert("Distributor/Firm not found. Please login again.");
    }

    try {
      const res = await fetch(`${API_URL}/area-to-party-mappings`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          companyCode: getCompanyCode(areaToPartyCompany),
          companyName: getCompanyName(areaToPartyCompany),

          mappings: mappedRows.map((row) => ({
            accountCode: row.accountCode,
            accountName: row.accountName,
            areaCode: row.areaCode,
            areaName: row.areaName,
          })),

          distributorId,
          firmId,
          firmName,
        }),
      });

      const result = await res.json();

      if (!res.ok) {
        return alert(result.message || "Area To Party mapping save failed");
      }

      alert("Area To Party mapping saved successfully!");
    } catch (error) {
      console.error(error);
      alert("Server not connected. Area To Party mapping save failed.");
    }
  };

  const resetAreaToPartyMapping = () => {
    setAreaToPartyCompany(null);
    setAreaToPartyData([]);
    setAreaToPartyEditingRow(-1);
    setAreaToPartyEditingCell('');
    setShowAreaToPartyDropdown(false);
  };
  /* =========================================================
   LOAD TRANSFER PAGE
   ========================================================= */
  /* =========================================================
     LOAD TRANSFER PAGE
     ========================================================= */

